/* 全分野版「つながり」データ (v170): 論点マスタ411件と選択肢単位タグ1975問×5肢。
 * 生成元: build/topics-proto/masters-all.json / choicetags-all.json
 * 生成: build/make-topics-all-data.mjs（手で編集しないこと） */
const PT_TOPIC_MASTER=[{"name":"デルマトームと反射の髄節","scope":"皮膚分節（デルマトーム）と体表指標の髄節対応、および深部腱反射の反射中枢の髄節を扱う。反射の求心路・遠心路を担う脳神経は脳神経反射の論点に入る。"},{"name":"上皮組織の種類と分布","scope":"線毛上皮・重層扁平上皮・扁平上皮など上皮の種類と、どの臓器・部位にあるかの対応を扱う。個別臓器の構造そのものは各臓器の論点に入る。"},{"name":"上肢の末梢神経と支配筋・感覚領域","scope":"正中・尺骨・橈骨神経と前骨間・後骨間神経の支配筋の組合せ、Froment徴候、手の感覚支配領域、絞扼部位を扱う。神経叢レベルでの障害は腕神経叢の論点に入る。"},{"name":"体性感覚の伝導路","scope":"温痛覚（外側脊髄視床路）など体性感覚の上行路の走行・交叉と、視床への入力（内側毛帯）を扱う。視覚・聴覚の特殊感覚路は含めない。"},{"name":"体表から触知できる構造とランドマーク","scope":"体表から触知できる筋・骨・腱の同定と、胸骨角・ヤコビー線などの体表ランドマークと椎骨レベルの対応を扱う。動脈・神経の触知は次の論点に入る。"},{"name":"冠状動脈の走行と灌流域","scope":"冠状動脈の起始・分枝と灌流域（心室中隔前方2/3など）を扱う。弁や中隔など心臓の形態は心臓の構造の論点に入る。"},{"name":"動脈と末梢神経の走行・触知部位","scope":"動脈の走行と脈拍の触知部位の組合せ、および尺骨神経など末梢神経が体表から触知できる部位を扱う。動脈の分枝そのものは血管の論点に入る。"},{"name":"回旋筋腱板の構成と停止","scope":"回旋筋腱板を構成する筋の同定と、上腕骨大・小結節への停止を扱う。腱板以外の肩周囲筋の付着は付着部の論点に入る。"},{"name":"外眼筋とその神経支配","scope":"外眼筋の種類と動眼・滑車・外転神経による支配、筋滑車をもつ上斜筋を含めた組合せを扱う。眼球壁や瞳孔など眼球自体の構造は眼球の論点に入る。"},{"name":"大動脈とその分枝","scope":"大動脈弓の分枝と左右差、左右一対の有無、動脈壁の構造を扱う。脳へ向かう動脈の灌流域は脳の動脈の論点に入る。"},{"name":"大脳基底核・小脳核と皮質下構造","scope":"大脳基底核の構成（被殻など）、小脳深部核（歯状核）、黒質など皮質下構造の同定と役割を扱う。基底核を経由する伝導路の問題は錐体路の論点に入る。"},{"name":"大脳皮質の機能局在","scope":"一次運動野・一次体性感覚野・運動前野・前頭前野・縁上回など大脳皮質の領野と部位・機能の対応、体性感覚地図（Penfield）の局在を扱う。皮質下の核は含めない。"},{"name":"平衡聴覚器の構造","scope":"中耳（耳小骨・耳管）と内耳（蝸牛・半規管・膜迷路）の構成要素と、半規管・前庭器の受容器を扱う。聴覚伝導路は伝導路の論点に入る。"},{"name":"後腹膜臓器と腹膜","scope":"一次・二次後腹膜臓器の同定（膵臓・腎臓・十二指腸など）と腹膜の関係を扱う。各臓器自体の内部構造は各臓器の論点に入る。"},{"name":"心臓の構造と位置関係","scope":"心房中隔（卵円窩）、房室弁、心臓の位置と断面での前後関係、冠静脈洞の開口を扱う。冠状動脈の走行・灌流域は冠状動脈の論点に入る。"},{"name":"手の筋と手根管・母指の腱","scope":"手の外来筋と内在筋の区別、手指の運動に作用する筋、手根管の通過物、母指の伸筋・外転筋の腱を扱う。手根骨の配列は手根骨の論点に入る。"},{"name":"手根骨・足根骨と足部の関節・アーチ","scope":"手根骨・足根骨の配列と隣接関係、Lisfranc関節などの足部の関節構成、足アーチを形成する骨を扱う。足部に付着する筋は筋の付着部の論点に入る。"},{"name":"気道と肺・胸膜の構造","scope":"気管・気管支の区分と構造（軟骨・平滑筋）、左右主気管支の差、肺の区域と縦隔面の接触物、胸膜の連続を扱う。咽頭と耳管の交通も含める。"},{"name":"生殖器と内分泌腺","scope":"女性生殖器の構造と卵巣周期のホルモン調節、および甲状腺など内分泌腺の分泌物を扱う。胚葉由来の腺（松果体など）は胚葉の論点に入る。"},{"name":"眼球の構造と光の経路","scope":"眼球壁・虹彩と瞳孔筋・前眼房・網膜（黄斑）など眼球の構造と、光が網膜に達する経路を扱う。外眼筋とその神経支配は外眼筋の論点に入る。"},{"name":"筋の位置関係と断面解剖","scope":"図示された断面・表面解剖で筋の位置関係から筋を同定する問題（下腿・足関節周囲の腱、大腿断面、前腕の筋など）を扱う。触知できるかどうかの問題はランドマークの論点に入る。"},{"name":"筋の作用の組合せ","scope":"個々の筋とその作用の正しい組合せ（前鋸筋・上腕筋・内がえし筋など）を扱う。付着部や神経支配の組合せは含めない。"},{"name":"細胞・組織の基礎","scope":"細胞小器官の機能、グリア細胞の種類と髄鞘形成、骨格筋線維・筋節の微細構造を扱う。上皮や胚葉は含めない。"},{"name":"股関節の形態と靱帯","scope":"寛骨臼の向き、頸体角、大腿骨頭靱帯と骨頭の血液供給、股関節周囲靱帯の緊張を扱う。股関節に作用する筋は含めない。"},{"name":"股関節・下肢の筋の付着部","scope":"大転子・鵞足・脛腓骨・足部など下肢の筋の付着部の同定を扱う。股関節自体の形態・靱帯は股関節の論点に入る。"},{"name":"肩・上肢の筋の付着部","scope":"肩周囲と上肢の筋の起始・停止（腸骨稜・橈骨粗面・小結節・大結節・中手骨底・胸椎への付着など）を扱う。回旋筋腱板の構成は腱板の論点に、作用の組合せは作用の論点に入る。"},{"name":"胚葉と器官の由来","scope":"外胚葉・中胚葉・内胚葉の三胚葉からどの組織・器官が発生するかを扱う。発生した後の成体の構造は含めない。"},{"name":"脊柱・頸椎の形態と靱帯","scope":"頸椎の特徴（環椎・第7頸椎など）と脊柱管・脊柱の靱帯（後縦靱帯など）の走行を扱う。椎骨レベルの体表指標はランドマークの論点に入る。"},{"name":"脊髄の形態と神経細胞体の所在","scope":"脊髄の外形・下端の位置・灰白質の構造と、感覚一次ニューロン・運動ニューロン・交感神経の細胞体の所在（後根神経節・前角・側角）を扱う。伝導路の走行は伝導路の論点に入る。"},{"name":"脳の動脈と灌流域","scope":"内頸動脈・椎骨脳底動脈系の分枝、大脳動脈輪の構成、各大脳動脈の灌流域（視床・被殻など）を扱う。頭頸部以外の動脈分枝は大動脈の論点に入る。"},{"name":"脳幹の構造と小脳脚・脳神経核","scope":"小脳脚の連絡、脳神経核の位置（橋など）、脳幹から出る脳神経を扱う。中脳の断面図での病変部位同定は皮質下構造の論点に入る。"},{"name":"脳神経と頭頸部筋の支配","scope":"三叉神経―咀嚼筋、顔面神経―表情筋、舌下神経―舌筋、反回神経の走行と喉頭筋支配など、脳神経と支配筋の組合せを扱う。顔面神経障害の症状（兎眼）も含める。外眼筋は外眼筋の論点に入る。"},{"name":"脳神経の分類と機能","scope":"脳神経の感覚・運動・混合の分類、味覚・顔面感覚・自律神経機能など働きの組合せ、化学受容器（頸動脈小体）の求心路を扱う。支配筋の組合せは次の論点に、反射は脳神経反射の論点に入る。"},{"name":"脳神経反射","scope":"対光反射・角膜反射など、脳神経が求心路・遠心路を担う反射の組合せを扱う。脊髄反射の髄節はデルマトームと反射の論点に入る。"},{"name":"脳膜・脳脊髄液と頭痛の受容器","scope":"くも膜下腔など脳脊髄膜の構造、脳脊髄液の流路（中脳水道など）、白質と灰白質の分類、および頭痛の痛覚受容器の分布を扱う。硬膜静脈洞など静脈系は含めない。"},{"name":"腎臓と尿路の構造","scope":"腎臓の構造（ネフロン・Henle係蹄）と内分泌機能、膀胱・尿管・尿道の構造と男女差を扱う。腎臓が後腹膜にあることは後腹膜の論点に入る。"},{"name":"腕神経叢とその枝","scope":"腕神経叢の神経束・終末枝と支配筋（筋皮神経・腋窩神経・胸背神経・肩甲背神経など）、神経束障害で低下する筋を扱う。個別の末梢神経の走行・感覚領域は上肢末梢神経の論点に入る。"},{"name":"腰・仙骨神経叢と下肢の神経支配","scope":"腰神経叢・仙骨神経叢の枝（大腿神経・閉鎖神経など）と下肢筋の神経支配、二重神経支配の筋、大腿三角と神経の関係を扱う。下肢の動脈・神経の触知は触知部位の論点に入る。"},{"name":"膝関節の構造（半月板・膝蓋骨）","scope":"半月板の形態・付着・血行と、膝蓋骨の形態と伸筋機構における役割を扱う。膝の靱帯や運動学は含めない。"},{"name":"視覚と聴覚の伝導路","scope":"視神経から視覚野への視覚伝導路（外側膝状体・視放線）と、聴覚路（外側毛帯・上側頭回）を扱う。眼球・内耳の構造そのものは感覚器の論点に入る。"},{"name":"錐体路と錐体外路","scope":"皮質脊髄路の走行（大脳脚・内包・錐体など）と、錐体外路に含まれるもの・含まれないものの区別を扱う。大脳基底核の構成は皮質下構造の論点に入る。"},{"name":"関節の付属構造（関節唇・関節円板）","scope":"関節唇をもつ関節と関節円板を有する関節の同定を扱う。半月板は膝関節の論点に、関節の形状分類は分類の論点に入る。"},{"name":"関節の分類と運動軸","scope":"関節の形状による分類（蝶番・車軸・平面・らせん関節など）と運動軸の数の対応を扱う。関節唇や半月板などの付属構造は含めない。"},{"name":"静脈・門脈とリンパの還流","scope":"大静脈へ流入する静脈（奇静脈・肝静脈・腎静脈）、門脈の形成と流入血管、胸管とリンパ還流の経路を扱う。動脈系は含めない。"},{"name":"頭頸部と体幹の筋","scope":"咀嚼筋・表情筋・頸部の筋（斜角筋など）と腹直筋・白線など体幹の筋の同定と作用を扱う。四肢の筋は含めず、支配神経の組合せは脳神経の論点に入る。"},{"name":"食道と胃の解剖","scope":"食道の狭窄部と走行、胃の部位（噴門・幽門・胃底）と腺の分布、小網・大網による臓器のつながりを扱う。口腔と膵臓は含めない。"},{"name":"骨の構造と骨折・牽引の基礎","scope":"皮質骨・海綿骨・骨膜・骨髄など骨の組織と構造、骨細胞の働きを扱う。骨折の名称と部位、直達・介達牽引の区別もここに含める。"},{"name":"ガス交換と酸素解離曲線","scope":"肺拡散に影響する因子、酸素解離曲線とBohr効果による末梢組織への酸素供給、肺コンプライアンスと機能的残気量を扱う。血液ガス値の判定は含まない。"},{"name":"シナプス伝達と神経筋接合部","scope":"シナプスで伝達物質が放出される流れと、神経筋接合部の伝達物質・薬物や毒素の作用部位を扱う。筋そのものの収縮機構は含まない。"},{"name":"下垂体ホルモンと分泌調節","scope":"下垂体前葉・後葉から分泌されるホルモンの種類と、標的ホルモンへのフィードバック調節、乳汁分泌への作用を扱う。"},{"name":"伸張反射と筋紡錘","scope":"筋紡錘の求心性線維（Ia・II群）と伸張反射の反射弓、深部腱反射・H反射、γ運動ニューロンの役割を扱う。"},{"name":"体温調節と視床下部","scope":"体温調節の中枢である視床下部の働きと、熱産生・熱放散の仕組み、体温の日内変動などホメオスターシスの維持を扱う。"},{"name":"免疫と抗体・免疫グロブリン","scope":"体液性免疫と形質細胞・B細胞、免疫グロブリンのクラスと機能、一次免疫応答で最初に産生される抗体、アレルギーの型との関与を扱う。"},{"name":"内分泌腺とホルモンの分泌・異常","scope":"ホルモンの産生・分泌部位の組合せ、ホルモンの化学的性質（水溶性・脂溶性）、内分泌異常と病態の組合せを扱う。下垂体・副腎など個別の腺の分泌調節は含まない。"},{"name":"副腎ホルモン","scope":"副腎皮質ホルモン（コルチゾールの作用・日内変動・生合成）と副腎髄質ホルモン（カテコールアミン）の分泌と作用の区別を扱う。"},{"name":"加齢に伴う生理機能の変化","scope":"加齢により増加・低下する生理機能の変化（呼吸機能・免疫機能を含む臓器機能の変化）を扱う。特定の疾患による変化は含まない。"},{"name":"呼吸力学と呼吸筋・呼吸音","scope":"呼吸運動に伴う胸腔内圧の変化、吸気・呼気筋（努力呼吸時の補助筋を含む）、体位による換気・含気分布、呼吸音の発生と特徴を扱う。肺気量の分画は含まない。"},{"name":"呼吸調節と酸塩基平衡","scope":"化学受容器による呼吸調節、動脈血液ガスの読み方と酸塩基平衡障害の分類・代償、呼吸不全の型とA-aDO2を扱う。"},{"name":"嚥下の生理","scope":"摂食嚥下の咽頭期に生じる現象と嚥下反射（喉頭挙上・気道防御など）を扱う。嚥下中枢の所在そのものは含まない。"},{"name":"基礎代謝とエネルギー代謝の指標","scope":"基礎代謝量・安静時代謝量とその変動要因、METs・エネルギー代謝率（RMR）・呼吸商などの指標と計算を扱う。"},{"name":"大脳・基底核・小脳の中枢機能","scope":"一次運動野と皮質脊髄路、基底核（ドーパミン系）と小脳による運動制御、大脳辺縁系の機能、神経可塑性による回復機序を扱う。"},{"name":"心筋の性質と心周期・心音","scope":"心筋の活動電位と不応期、自動能と収縮力の調節（Frank-Starlingの法則など）、心周期における弁の動きと心音を扱う。"},{"name":"心臓の刺激伝導系と心電図","scope":"刺激伝導系の構成と興奮が伝わる順序、心電図波形が表す心臓の興奮過程を扱う。心筋細胞の性質そのものは含まない。"},{"name":"性周期と生殖器の生理","scope":"月経周期・卵巣周期とエストロゲン・プロゲステロンの作用、基礎体温の変化、男性生殖器の機能と自律神経支配を扱う。"},{"name":"感覚受容器と痛覚","scope":"皮膚の感覚受容器の種類（侵害受容器・自由神経終末など）と痛覚の受容を扱う。筋紡錘などの深部感覚受容器と伝導路は含まない。"},{"name":"排便機構と神経制御","scope":"排便反射と肛門括約筋の働き、排便中枢、随意的な排便制御に関わる神経を扱う。"},{"name":"排尿機構と神経支配","scope":"蓄尿と排尿の切り替えと、それに関与する自律神経・体性神経（陰部神経など）の役割を扱う。排便の制御は含まない。"},{"name":"消化液分泌の調節","scope":"胃液・膵液・唾液の分泌を促す因子と調節を扱い、ガストリンや、内因子とビタミンB12吸収の関係も含む。酵素の作用そのものは含まない。"},{"name":"消化酵素と消化・吸収","scope":"消化酵素の作用と、糖質・脂質の消化吸収の流れ（胃での消化・吸収を含む）を扱う。消化液の分泌を促す調節は含まない。"},{"name":"甲状腺とカルシウム代謝・骨代謝","scope":"甲状腺ホルモンとカルシトニン、副甲状腺ホルモンによるカルシウム代謝の調節と腸管でのカルシウム吸収、骨代謝とリモデリングを扱う。"},{"name":"神経の興奮伝導と線維分類","scope":"膜電位・活動電位の基礎、興奮伝導の性質と跳躍伝導、神経線維の分類（線維径・伝導速度・痛覚線維）と感覚伝導路を扱う。神経伝導検査・筋電図の所見の読み分けも含む。"},{"name":"筋収縮の機構と収縮様式","scope":"滑走説と筋節の構造変化、興奮収縮連関におけるCa²⁺の結合と回収を中心に、平滑筋との違い、遠心性収縮など収縮様式が生じる場面も含む。筋線維タイプの性質は含まない。"},{"name":"筋線維タイプと筋疲労","scope":"タイプI・II筋線維の特徴の比較と、運動による疲労時に筋内で起こる変化（乳酸の増加など）を扱う。"},{"name":"糖代謝とエネルギー産生","scope":"解糖系とクエン酸回路の流れと生成物（ピルビン酸・乳酸など）、嫌気的代謝の位置づけを扱う。代謝量の指標や計算は含まない。"},{"name":"細胞小器官と細胞の基礎機能","scope":"細胞小器官の構造と働き（ATP合成、タンパク質の修飾、リボソーム形成など）を中心に、細胞分裂の開始に関わる構造と、組織の再生能力の違いも含む。遺伝情報の伝達過程そのものは含まない。"},{"name":"肝臓と胆汁の機能","scope":"肝臓の機能（尿素回路・薬物代謝など）と、胆汁の生成・働き・腸肝循環を扱う。脂質の消化吸収そのものは含まない。"},{"name":"肺気量分画と肺機能検査","scope":"肺気量・肺容量の分画とスパイログラムの読み方、肺胞換気量の算出、肺機能検査による換気障害の判定とCOPDにおける分画の変化を扱う。"},{"name":"脳幹の反射中枢","scope":"角膜反射など脳神経が関与する反射弓と、嚥下中枢をはじめとする脳幹にある反射中枢の所在を扱う。脊髄レベルの伸張反射は含まない。"},{"name":"脳波の基礎","scope":"脳波の帯域（α波など）の特徴と、安静閉眼時の基礎律動、脳波検査の読み方を扱う。"},{"name":"腎臓の内分泌と尿濃縮の調節","scope":"腎臓から分泌されるホルモン（エリスロポエチンなど）と、その産生を促す条件、集合管での尿濃縮に関わるADH・アルドステロンの作用を扱う。"},{"name":"腎臓の構造と尿生成","scope":"ネフロンの構造と糸球体ろ過、尿細管の部位別の再吸収と分泌を扱う。尿濃縮のホルモン調節は含まない。"},{"name":"自律神経の作用と臓器支配","scope":"交感・副交感神経が各臓器に及ぼす作用、二重支配と拮抗作用、伝達物質による刺激と反応の組合せを扱う。起始・経路は含まない。"},{"name":"自律神経の起始・経路と障害","scope":"交感・副交感神経の起始レベルと節前・節後線維の経路（副腎髄質の支配を含む）、自律神経障害の症状（起立性低血圧など）を扱う。各臓器への作用そのものは含まない。"},{"name":"血圧と循環調節","scope":"血圧の正常値と測定、圧受容器反射（頸動脈洞反射）、昇圧作用を持つホルモン、血流量の局所性調節と微小循環を扱う。運動時の循環変化は含まない。"},{"name":"血液凝固と線溶","scope":"凝固因子とフィブリン形成、線維素溶解系の働き、ワルファリンとビタミンKの関係を扱う。"},{"name":"血球の種類と機能","scope":"赤血球・白血球・血小板の種類と働きの組合せを扱う。抗体産生の仕組みと凝固因子は含まない。"},{"name":"血糖調節ホルモン","scope":"血糖を上昇・下降させるホルモンの作用（膵島ホルモンを含む組合せ）を扱う。副腎髄質からの分泌そのものは含まない。"},{"name":"視覚の生理","scope":"視細胞・盲点・眼の調節機構など、視覚の受容と伝達の仕組みを扱う。他の感覚受容器は含まない。"},{"name":"運動単位とサイズの原理","scope":"運動単位の定義、神経支配比、サイズの原理による動員の順序を扱う。"},{"name":"運動時のエネルギー供給と酸素摂取","scope":"運動時のATP供給系（無酸素系・有酸素系）の特徴と、漸増負荷時の酸素摂取量・換気性作業閾値の変化を扱う。安静時の基礎代謝は含まない。"},{"name":"運動時の循環応答とトレーニング適応","scope":"運動時の血流再配分と心拍出量の応答、持久力トレーニングによる循環適応（最大酸素摂取量、スポーツ心臓など）と、その逆方向である廃用によるデコンディショニングを扱う。"},{"name":"遺伝情報の伝達とDNA・RNA","scope":"DNAとRNAの塩基組成の違い、セントラルドグマとコドン・翻訳の流れなど、遺伝情報がタンパク質になるまでの過程を扱う。"},{"name":"作業姿勢と腰椎負荷","scope":"姿勢の違いによる椎間板内圧・腰椎負荷の大きさの順序と、腰痛予防を目的とした作業姿勢の指導を扱う。"},{"name":"前腕・手関節・手指の運動と筋","scope":"前腕の回内・回外、手関節の屈曲・伸展・橈屈・尺屈、手指の筋と手の内在筋の作用を扱う。"},{"name":"力学の基礎とトルク・モーメント","scope":"力・仕事・仕事率などの力学の基礎量とSI単位、およびモーメントアームを用いたトルク・筋力のつり合いの計算を扱う。"},{"name":"加齢と歩行速度による歩行の変化","scope":"若年者と比較した高齢者の歩行特性、および歩行速度を速めた際の歩行周期・歩幅・筋活動などの変化を扱う。"},{"name":"呼吸運動と呼吸筋","scope":"安静時および努力性の吸気・呼気に働く筋の同定と、臥位などの体位による呼吸機能の変化を扱う。"},{"name":"咀嚼・嚥下の筋","scope":"咀嚼筋と下顎の運動の組合せ、および嚥下反射時の舌骨筋群の挙上・下降作用を扱う。"},{"name":"大腿・下腿・足部の筋の作用","scope":"ハムストリングスや鵞足を構成する筋など大腿の筋、下腿の筋区画とその作用、筋の足部への作用、二関節筋の働きを扱う。"},{"name":"姿勢の安定性と姿勢制御戦略","scope":"支持基底面と安定性の条件、外乱に対する足関節戦略などの姿勢応答と筋活動の順序、抗重力筋、静的姿勢での床反力と重心のつり合いを扱う。"},{"name":"歩行の時間・距離因子と速度計算","scope":"歩幅・重複歩距離・歩隔・歩行率（ケイデンス）の定義と相互関係、および歩行速度などの計算問題を扱う。"},{"name":"歩行の決定要因と重心・骨盤の運動","scope":"正常歩行の決定要因（determinants）、骨盤の回旋・側方傾斜、歩行に伴う身体重心の上下・側方移動を扱う。"},{"name":"歩行分析と床反力・関節モーメント","scope":"歩行時の床反力（垂直分力の波形など）と関節モーメント、および三次元歩行分析装置などの歩行分析の方法を扱う。"},{"name":"歩行周期と下肢筋活動","scope":"歩行周期の各相における下肢筋の活動時期・活動パターンの判読と、荷重応答期などの遠心性収縮を扱う。"},{"name":"歩行周期の相と区分","scope":"立脚期・遊脚期の区分と各相の名称・境界事象、単脚支持期と両脚支持期、歩行周期の割合を扱う。"},{"name":"異常歩行の特徴と原因","scope":"筋力低下・関節拘縮・関節変形・片麻痺などに伴う異常歩行の特徴と、その原因となる筋や病態との対応を扱う。"},{"name":"立位姿勢のアライメントと重心線","scope":"成人の正常立位姿勢における重心線の通過位置、脊柱の生理的弯曲、基本的立位姿勢の観察基準を扱う。"},{"name":"筋の伸張条件とストレッチング","scope":"筋の作用と伸張肢位の逆関係、二関節筋が伸張される肢位の条件と、ストレッチングで伸張される筋の判定を扱う。"},{"name":"股関節の運動と作用筋","scope":"股関節の屈曲・伸展・内外転・内外旋に作用する筋の組合せと、肢位による作用の変化（深層外旋筋群など）を扱う。"},{"name":"肩甲骨の運動と肩甲上腕リズム","scope":"肩甲骨の挙上・下制・上方回旋・下方回旋に作用する筋とフォースカップル、肩甲上腕リズムの角度配分、翼状肩甲を扱う。"},{"name":"肩関節の運動と作用筋","scope":"肩甲上腕関節の屈曲・伸展・外転・水平運動・内外旋に作用する筋と回旋筋腱板の働きを扱う。"},{"name":"膝関節の運動学と靱帯","scope":"膝関節の転がり・滑り運動、終末伸展回旋機構（スクリューホーム機構）、靱帯・半月板の機能と屈曲制限の因子を扱う。"},{"name":"足関節・足部の構造とアーチ","scope":"足関節・足部の関節の運動学と、内側縦アーチをはじめとする足部アーチの構成・支持機構とウィンドラス機構を扱う。"},{"name":"運動学習とフィードバック","scope":"結果の知識（KR）とパフォーマンスの知識（KP）の区別など、運動学習におけるフィードバックの種類と与えられる場面を扱う。"},{"name":"運動学習の過程と練習方法","scope":"運動学習の段階と学習曲線・プラトー、転移、学習効率を高める練習方法とフィードバックの与え方を扱う。"},{"name":"運動強度（METs）と運動時の生体応答","scope":"METsによる運動強度の表記とエネルギー消費量の計算、および運動負荷時の循環応答（一回拍出量など）を扱う。"},{"name":"関節運動の基礎と可動域測定","scope":"関節の分類と運動軸の数、他動運動の最終域感（end feel）、関節可動域測定法の基本軸・移動軸を扱う。"},{"name":"随意運動と運動制御の中枢機構","scope":"運動野・錐体路による随意運動の機構と、運動の企画・調節に関わる小脳および大脳基底核の役割を扱う。"},{"name":"頸部・体幹の運動と作用筋","scope":"頸部筋と体幹筋の屈曲・伸展・側屈・回旋における作用、脊椎の回旋運動、体幹運動を制動する靱帯を扱う。"},{"name":"骨格筋の収縮機構と筋力","scope":"筋節・フィラメントの構造、運動単位と神経支配比・張力の調節、収縮様式（遠心性収縮を含む）と筋力増強運動の原則を扱う。"},{"name":"Guillain-Barré症候群と炎症性脱髄性末梢神経障害","scope":"Guillain-Barré症候群の臨床像・病型（脱髄型と軸索型）・検査（髄液・神経伝導検査）と、慢性炎症性脱髄性多発ニューロパチー（CIDP）を扱う。中枢の脱髄（多発性硬化症）は別の論点とする。"},{"name":"Parkinson病の症候と治療","scope":"Parkinson病の運動・非運動症状と徴候（固縮・振戦・突進現象など）、疫学、L-dopaなどの治療薬と運動合併症（wearing-off・on-off現象）、脳深部刺激療法やボツリヌス療法など治療法の適否を扱う。重症度判定と歩行指導、UPDRS等の評価は別の論点とする。類縁の変性疾患は別の論点とする。"},{"name":"てんかんの発作型と治療","scope":"てんかんの発作型（欠神・複雑部分・Jackson発作など）と意識障害の有無、誘因、高齢初発てんかんの特徴、抗てんかん薬の副作用を扱う。脳波所見の詳細は含めない。"},{"name":"アレルギーと免疫異常","scope":"アレルギーの型分類（GellとCoombs）とアナフィラキシー、全身性エリテマトーデスやBehçet病などの自己免疫疾患、HIV感染・免疫不全による日和見感染、移植片対宿主病を扱う。関節リウマチは整形の論点で扱う。"},{"name":"ショックの分類と病態","scope":"ショックの分類（分布異常性・心原性・循環血液量減少性・神経原性など）と、末梢血管抵抗・心拍数などの血行動態の変化、初期症状を扱う。アナフィラキシーの免疫機序は免疫の論点に譲る。"},{"name":"ステロイド薬の副作用","scope":"副腎皮質ステロイドの全身性副作用（大腿骨頭壊死・骨粗鬆症など）と長期投与で生じやすい病態を扱う。気管支喘息の治療薬としての位置づけは呼吸器の論点で扱う。"},{"name":"フレイルとサルコペニア","scope":"フレイルの判定要件（Friedの表現型など）とサルコペニアの診断基準、両者に共通する評価項目（握力・歩行速度）を扱う。低栄養一般は栄養障害の論点に譲る。"},{"name":"上肢の末梢神経損傷（腕神経叢を含む）","scope":"腕神経叢損傷の病態と腫瘍浸潤（Pancoast腫瘍）、骨折・脱臼に合併する神経麻痺（橈骨神経・腋窩神経）と尺骨神経麻痺の装具適応を扱う。絞扼障害は別の論点とする。"},{"name":"中枢神経系の感染症・プリオン病と髄膜徴候","scope":"中枢神経系の感染症と病原体の組合せ、プリオン病（Creutzfeldt-Jakob病）の感染性、髄膜刺激徴候を扱う。全身の感染症の基礎は病原体の論点に譲る。"},{"name":"先天性の中枢神経疾患と先天感染","scope":"二分脊椎など中枢神経の先天奇形とその合併症、先天性風疹など胎児期感染による先天異常、脳性麻痺の病型（アテトーゼ型など）を扱う。先天性心疾患は循環器の論点で扱う。"},{"name":"先天性心疾患","scope":"心室中隔欠損症など先天性心疾患の頻度と、左右短絡・Fallot四徴症の血行動態を扱う。後天性の弁膜症や心不全は含めない。"},{"name":"内分泌・代謝異常の症候","scope":"副甲状腺機能低下によるテタニーなど内分泌異常と症候の組合せ、甲状腺中毒によるミオパチー、Wilson病の銅代謝異常を扱う。糖尿病とその合併症は別の論点とする。"},{"name":"出血傾向と凝固異常","scope":"血友病などの凝固系の異常による出血傾向の特徴と、ワルファリンなど抗凝固薬の作用機序・相互作用（ビタミンK・納豆）を扱う。血栓塞栓症そのものは別の論点とする。"},{"name":"創傷治癒と組織の修復・再生","scope":"肉芽組織の特徴、創傷治癒を遅延させる因子、組織・細胞の再生能力の差を扱う。熱傷創そのものの深度や治療は含めない。"},{"name":"呼吸器疾患（間質性肺疾患・喘息・気胸・COPD）","scope":"間質性肺疾患の所見（拡散障害・線維化・画像）と、気管支喘息の治療薬、自然気胸の特徴、COPDの管理を扱う。肺炎などの呼吸器感染症は含めない。"},{"name":"変形性関節症","scope":"変形性膝・股関節症の病態・症状・画像所見と一次性と二次性の区別、Heberden・Bouchard結節、理学療法の適否を扱う。関節リウマチとの鑑別はリウマチの論点に譲る。"},{"name":"多発性硬化症と中枢神経の脱髄","scope":"多発性硬化症の病態（中枢神経の脱髄）と診断（MRI）、Lhermitte徴候・痙縮・感覚障害など再発に伴う症候を扱う。末梢の脱髄（Guillain-Barré症候群など）は別の論点とする。"},{"name":"大動脈と末梢血管の疾患","scope":"大動脈解離の続発症、血管疾患と関連因子の組合せ、閉塞性動脈硬化症などの末梢動脈疾患とBuerger病を扱う。静脈血栓塞栓症は含めない。"},{"name":"失語症と高次脳機能障害","scope":"失語症の分類（Broca・伝導・健忘失語など）と流暢性・理解・復唱の対応、大脳葉の損傷による失行・病態失認などの高次脳機能障害を扱う。認知症そのものは別の論点とする。"},{"name":"小児の骨端症と骨・関節疾患","scope":"Perthes病・大腿骨頭すべり症・Freiberg病など小児の骨端症の好発部位と特徴、小児骨折後の変形（外反肘）を扱う。成人の骨壊死は骨折合併症の論点に譲る。"},{"name":"心原性脳塞栓とその原因","scope":"心房細動の治療と脳塞栓の原因としての位置づけ、心原性脳塞栓症の原因疾患、感染性心内膜炎から生じる脳塞栓を扱う。脳梗塞の画像や局在症状は神経の論点で扱う。"},{"name":"心筋梗塞と心不全","scope":"急性心筋梗塞の胸痛の特徴と心筋マーカーの推移、うっ血性心不全の症状・徴候を扱う。狭心症との鑑別や心房細動は別の論点に譲る。"},{"name":"排尿障害（神経因性膀胱と尿失禁）","scope":"神経因性膀胱の分類（核上型・低活動性など）と排尿管理、尿失禁の分類と機序（腹圧性など）を扱う。脊髄損傷そのものの合併症は脊髄損傷の論点に譲る。"},{"name":"末梢神経の絞扼障害と損傷の分類","scope":"手根管症候群など絞扼性神経障害の部位と症候の組合せ、前・後骨間神経麻痺、末梢神経損傷の分類（Seddon分類）と予後を扱う。骨折に合併する神経損傷は上肢損傷の論点に譲る。"},{"name":"染色体異常と遺伝形式","scope":"常染色体トリソミー（Down症候群）などの染色体異常の分類と、疾患と遺伝形式の組合せを扱う。個別の遺伝性疾患の臨床像は各疾患の論点で扱う。"},{"name":"栄養障害・ビタミン欠乏と低栄養","scope":"ビタミンと欠乏症候の組合せ、高齢者の低栄養と関連する病態・関連しにくい病態の見分けを扱う。フレイルやサルコペニアの判定そのものは別の論点とする。"},{"name":"浮腫とリンパ浮腫","scope":"圧痕性・非圧痕性といった浮腫の分類と原因疾患、リンパ浮腫の病態と合併症（蜂窩織炎など）を扱う。心不全や腎不全による浮腫の機序の詳細は各疾患側で扱う。"},{"name":"消化管の術後合併症とイレウス","scope":"胃切除後症候群（逆流性食道炎など）と、イレウスの分類（機械的・機能的）と原因を扱う。胃全摘後の貧血は血液の論点で扱う。"},{"name":"炎症の病態（急性炎症と慢性炎症）","scope":"急性炎症の徴候と経過、急性炎症と比較した慢性炎症の特徴（線維化・血管増殖・肉芽腫など）を扱う。創傷治癒の過程は別の論点とする。"},{"name":"炎症性筋疾患（多発性筋炎・皮膚筋炎）","scope":"多発性筋炎・皮膚筋炎の検査所見（CK上昇）と合併症（間質性肺炎・悪性腫瘍）、予後を扱う。筋ジストロフィーや内分泌性ミオパチーは含めない。"},{"name":"熱傷の病態と治療","scope":"熱傷の深度判定と面積・重症度、受傷早期の病態（浮腫・ショック）と初期輸液、気道熱傷や植皮の生着条件を扱う。創傷治癒の総論は別の論点とする。"},{"name":"病原体と疾患（感染経路・毒素・発癌）","scope":"感染経路による病原体の分類、細菌毒素が原因となる疾患、肝炎ウイルスやHPVなど発癌に関わる病原体との組合せを扱う。個別の感染症の臨床像は各臓器の論点に譲る。"},{"name":"病因の分類と環境因子による障害","scope":"疾病の外因を物理的・化学的・生物学的要因に分ける分類と、アスベスト・喫煙・紫外線・有機水銀（水俣病）など環境因子による障害を扱う。個別疾患の病態そのものは各臓器の論点に譲る。"},{"name":"睡眠障害と精神疾患の治療","scope":"ナルコレプシーの症状、ベンゾジアゼピン系睡眠薬の副作用、パーソナリティ障害への治療介入を扱う。精神疾患の本格的な分類・治療は臨床心理・精神の分野が本来の置き場で、ここでは寄せられた問題の受け皿とする。"},{"name":"神経障害性疼痛（視床痛・帯状疱疹・幻肢痛）","scope":"視床痛（中枢性疼痛）の特徴とアロディニア、帯状疱疹に伴う疼痛、切断後の幻肢・幻肢痛を扱う。CRPSは別の論点とする。"},{"name":"筋ジストロフィー","scope":"Duchenne型筋ジストロフィーの遺伝・臨床徴候（登はん性起立・仮性肥大・呼吸障害）と筋強直性ジストロフィーの特徴（ミオトニア・遺伝形式）を扱う。炎症性筋疾患は別の論点とする。"},{"name":"糖尿病とメタボリックシンドローム","scope":"糖尿病性神経障害の感覚障害のパターンと、メタボリックシンドロームの診断基準を扱う。糖尿病性腎症は腎臓の論点、神経因性膀胱は排尿障害の論点で扱う。"},{"name":"細胞の適応性変化・障害と細胞死","scope":"萎縮・肥大・過形成・化生・異形成（前癌病変を含む）といった細胞の適応性変化と、アポトーシスと壊死の違いを扱う。炎症や腫瘍の総論は含めない。"},{"name":"肝・膵疾患とウイルス性肝炎","scope":"肝不全の症候（腹水など）、ウイルス性肝炎の型と予防（B型肝炎ワクチン）、急性膵炎の病態を扱う。肝炎ウイルスと発癌の組合せは病原体の論点に譲る。"},{"name":"肺炎と呼吸器感染症","scope":"大葉性肺炎の画像所見と、レジオネラ症など呼吸器感染症の感染源・感染経路を扱う。間質性肺疾患や気胸は別の論点とする。"},{"name":"脊椎・脊柱の疾患","scope":"腰椎椎間板ヘルニアの病態と神経根症状の対応、腰部脊柱管狭窄症の間欠性跛行、後縦靱帯骨化症、腰椎分離症・疲労骨折を扱う。脊髄損傷や脊椎への腫瘍転移は別の論点とする。"},{"name":"脊髄小脳変性症・多系統萎縮症と小脳症候","scope":"脊髄小脳変性症の特徴と評価（SARA・Frenkel体操）、多系統萎縮症の分類と自律神経障害・合併症、小脳障害一般の症候（筋緊張低下・ジスメトリー・運動失調）を扱う。"},{"name":"脊髄損傷の病態と合併症","scope":"外傷性脊髄損傷の疫学、脊髄ショック期の徴候、異所性骨化などの合併症を扱う。神経因性膀胱の管理は排尿障害の論点、Brown-Séquard症候群は脊髄症候群の論点で扱う。"},{"name":"脳出血と頭蓋内血腫","scope":"くも膜下出血の早期診断（単純CT）と外科治療、被殻・視床・小脳など部位別の脳出血の画像と症状、硬膜外血腫のCT所見を扱う。脳梗塞の画像は別の論点とする。"},{"name":"脳幹・脊髄の局在症候群と伝導路","scope":"延髄外側症候群（Wallenberg）やBrown-Séquard症候群など脳幹・脊髄の局在症候群と、血管領域・伝導路の交叉から症候を組み立てる問題を扱う。末梢神経の障害は含めない。"},{"name":"脳梗塞の局在症状","scope":"内包後脚・中大脳動脈領域・脳幹など梗塞部位と出現する症状の組合せを扱う。画像所見そのものや高次脳機能障害の分類は別の論点に譲る。"},{"name":"脳梗塞の画像診断","scope":"急性期脳梗塞におけるMRI拡散強調画像の有用性、CTとMRIの使い分け、陳旧性梗塞や多発性脳梗塞の画像所見を扱う。出血性病変のCT所見は脳出血の論点で扱う。"},{"name":"脳神経麻痺と嚥下障害","scope":"末梢性顔面神経麻痺（Bell麻痺）と咀嚼筋の神経支配、反回神経麻痺による嚥下咽頭期の障害、摂食嚥下の期と障害の対応を扱う。失語症などの高次脳機能障害は含めない。"},{"name":"脳腫瘍の部位・症状と悪性度","scope":"脳腫瘍の発生部位と局在症状の組合せ（下垂体腺腫の両耳側半盲・小脳橋角部の神経鞘腫など）と、神経膠芽腫など原発性脳腫瘍の悪性度を扱う。転移性腫瘍は転移の論点で扱う。"},{"name":"脳血管障害の病型と疫学","scope":"脳血管障害の病型別の発症頻度と疫学（脳梗塞が最多、くも膜下出血の性差など）を扱う。個別の診断画像や局在症状は別の論点とする。"},{"name":"腎不全・尿毒症の病態","scope":"尿毒症の病態（代謝性アシドーシスなど）と慢性腎臓病の臨床所見、尿検査所見と横紋筋融解症など腎障害に関わる検査の対応を扱う。透析療法そのものは別の論点とする。"},{"name":"腎疾患の原因と透析療法","scope":"慢性腎不全や糖尿病性腎症など腎疾患と原因の組合せ、透析導入の原因疾患・透析患者の死因など透析療法の疫学を扱う。尿毒症の病態そのものは別の論点とする。"},{"name":"腫瘍の基礎（良性と悪性の鑑別）","scope":"良性腫瘍と悪性腫瘍の鑑別点と悪性腫瘍細胞の特徴（異型性・核／細胞質比・分化度など）を扱う。個別の臓器癌の疫学や転移・治療は別の論点とする。"},{"name":"腫瘍の転移・病期と治療に伴う障害","scope":"骨転移の好発部位と症候、TNM分類、放射線療法の急性期・晩期副作用、がん緩和ケアにおける理学療法を扱う。原発巣ごとの特徴は各臓器の腫瘍の論点で扱う。"},{"name":"自律神経系に作用する薬物","scope":"抗コリン薬の作用・副作用と、コリンエステラーゼ阻害薬など自律神経系に作用する薬物の機序を扱う。個別疾患の治療薬（Parkinson病・てんかんなど）は各疾患の論点で扱う。"},{"name":"血液・リンパ系の腫瘍","scope":"多発性骨髄腫の主要所見（CRAB・病的骨折など）と悪性リンパ腫の基礎を扱う。他の固形癌は各臓器の論点で扱う。"},{"name":"複合性局所疼痛症候群（CRPS）","scope":"CRPSのtype I・type IIの分類と所見、肩手症候群やSudeck骨萎縮との関係、脳卒中後の出現時期を扱う。視床痛などの中枢性疼痛は別の論点とする。"},{"name":"認知症の分類と病理","scope":"Alzheimer型認知症のアミロイド沈着など型別の病理・頻度・症状（Lewy小体型の幻視、前頭側頭型、正常圧水頭症）、中核症状とMCIの疫学、治療可能な認知症の原因を扱う。"},{"name":"貧血の分類と巨赤芽球性貧血","scope":"貧血を産生低下・溶血・失血などの機序で分ける分類と、ビタミンB12・葉酸欠乏による巨赤芽球性貧血（胃全摘後の悪性貧血を含む）、鉄欠乏に伴う症候を扱う。"},{"name":"軟部組織損傷とスポーツ障害","scope":"半月板・前十字靱帯損傷とその検査、アキレス腱断裂、腱板断裂の画像検査、肩関節周囲炎、野球肘・離断性骨軟骨炎、槌指、捻挫後の靱帯と筋の対応を扱う。人名骨折や脱臼の分類は別の論点とする。"},{"name":"運動ニューロン疾患とポリオ後症候群","scope":"筋萎縮性側索硬化症の上位・下位運動ニューロン徴候と症例所見、ポリオ後症候群の診断基準と病態を扱う。筋ジストロフィーなど筋自体の疾患は含めない。"},{"name":"重症筋無力症","scope":"重症筋無力症の自己免疫機序、胸腺異常との関連、クリーゼの病態を扱う。神経筋接合部に作用する薬の機序は薬物の論点に譲る。"},{"name":"鎮痛薬と疼痛治療","scope":"NSAIDs・アスピリンの作用と副作用（胃潰瘍など）、オピオイドの副作用（便秘）、神経ブロックの適応と合併症を扱う。ステロイドの副作用は別の論点とする。"},{"name":"関節リウマチの手指変形","scope":"スワンネック変形・ボタン穴変形など関節リウマチにみられる手指変形の生じる関節と形態を扱う。外傷性の手指変形（槌指など）は軟部組織損傷の論点で扱う。"},{"name":"関節リウマチの病態と合併症","scope":"関節リウマチの症状・関節変形・頸椎病変、2010年分類基準と自己抗体、Steinbrocker分類、間質性肺炎などの関節外合併症を扱う。手指変形の細目は別の論点とする。"},{"name":"静脈血栓塞栓症","scope":"深部静脈血栓症の成因（不動・術後・Virchowの3徴）と診断マーカー（Dダイマー）、肺塞栓症への進展とその特徴を扱う。抗凝固薬の薬理は凝固異常の論点に譲る。"},{"name":"食道癌・胃癌・乳癌（固形癌の疫学と組織型）","scope":"食道癌（扁平上皮癌・飲酒喫煙）、胃癌（腺癌）、乳癌（好発部位）など固形癌の疫学・組織型・危険因子を扱う。腫瘍の総論や転移・病期は別の論点とする。"},{"name":"骨折と脱臼の分類・人名骨折","scope":"骨折の分類（完全・不完全骨折）とColles・Monteggia・Galeazzi・Bennett・Malgaigneなど人名のついた骨折の部位、関節脱臼の好発方向を扱う。骨折の合併症や治療は別の論点とする。"},{"name":"骨折の合併症（偽関節・骨壊死・拘縮）","scope":"偽関節や骨壊死を生じやすい骨折（舟状骨・大腿骨頸部・距骨など）と、Volkmann拘縮・コンパートメント症候群、上腕骨顆上骨折の循環障害、踵骨骨折後の変形性関節症を扱う。"},{"name":"骨粗鬆症と脆弱性骨折","scope":"原発性・続発性骨粗鬆症の分類と危険因子、診断基準に含まれる脆弱性骨折の部位、骨粗鬆症性椎体圧迫骨折を扱う。ステロイドによる骨粗鬆症の機序は薬物の論点にも現れる。"},{"name":"骨軟部腫瘍","scope":"骨肉腫の臨床像・画像所見と転移、良性の骨軟部腫瘍との鑑別、悪性が疑われる場合の生検による診断確定を扱う。転移性骨腫瘍は転移の論点で扱う。"},{"name":"高齢者の骨折","scope":"高齢者に多い大腿骨近位部骨折や恥骨骨折の特徴・危険因子と、上腕骨近位端骨折など転倒による骨折の初期対応を扱う。骨粗鬆症そのものは別の論点とする。"},{"name":"ADLの動作分析と指導","scope":"片麻痺・人工股関節術後のADL指導（脱臼肢位・着患脱健・病室環境設定）と、関節可動域制限がADL動作に与える影響を扱う。"},{"name":"Barthel Indexの項目と配点","scope":"Barthel Indexの項目別配点と、症例のADL状況からの採点を扱う。FIMとの使い分けは含まない。"},{"name":"Brunnstrom法ステージの判定","scope":"上・下肢のBrunnstrom法ステージと、可能な随意運動・テスト動作の組合せ（共同運動と分離運動）を扱う。"},{"name":"FIMの構成と採点","scope":"FIMの項目構成と7段階の採点（修正自立・最小介助など）、具体的な介助量からの得点判定と合計の計算を扱う。WeeFIMなど小児への適用も含む。"},{"name":"Fugl-Meyer Assessmentと脳卒中の姿勢異常","scope":"Fugl-Meyer Assessmentの構成・総点と、pusher症候群など脳卒中後の姿勢異常の評価を扱う。"},{"name":"IADLと基本的ADLの分類","scope":"IADLに含まれる項目と基本的ADLの区別、LawtonのIADLスケール、老研式活動能力指標の手段的自立項目を扱う。"},{"name":"Parkinson病の評価（UPDRS・Hoehn & Yahr）","scope":"UPDRSの評価項目の構成と、Hoehn & Yahr重症度分類の判定を扱う。"},{"name":"QOL・幸福感とがん全身状態の評価","scope":"PGCモラールスケールによる主観的幸福感と、Karnofsky Performance Statusなど、がん患者の全身状態・活動能力の評価尺度を扱う。"},{"name":"SIASの構成と評定","scope":"SIAS（脳卒中機能評価法）の評価項目と、麻痺側運動機能テストの評定・合計点を扱う。"},{"name":"バランス評価（BBS・FBS・FRT）","scope":"Berg Balance Scale・機能的バランス尺度（FBS）・Functional Reach Testの実施方法と、転倒リスクや経時変化の解釈を扱う。"},{"name":"フレイル・サルコペニア・ロコモの評価","scope":"フレイルの判定基準（Fried基準・基本チェックリスト）、サルコペニア（AWGS）の評価項目とスクリーニング、ロコモ度テスト、高齢者評価指標の総合的な解釈を扱う。"},{"name":"健康関連QOL評価（SF-36）","scope":"SF-36の8つの下位尺度と尺度の特徴、他のQOL評価尺度との区別を扱う。"},{"name":"動作・歩行の観察評価と異常歩行","scope":"立ち上がり・体幹前屈などの動作観察と代償、筋力低下・歩行障害の原因と異常歩行（Duchenne歩行など）の対応を扱う。"},{"name":"医療面接の質問技法","scope":"開かれた質問・閉じられた質問・焦点型質問など、問診における質問の種類と具体例の対応を扱う。"},{"name":"周径・身体計測と車椅子寸法","scope":"四肢の周径測定法、身体計測の基準点と方法、計測値に基づく車椅子の基本寸法を扱う。"},{"name":"呼吸困難の評価と嚥下・誤嚥の検査","scope":"mMRCスケールによる呼吸困難の段階付け、嚥下造影検査・嚥下内視鏡検査など嚥下の検査、誤嚥性肺炎の身体所見を扱う。"},{"name":"呼吸機能検査と動脈血ガス分析","scope":"スパイロメトリーの指標と計測の限界（肺気量分画）、換気障害のパターン、％1秒量の計算、動脈血ガス値からの呼吸様式の推定を扱う。"},{"name":"四肢長・肢長測定","scope":"四肢長の計測の起点・終点となる骨指標と測定部位、棘果長・転子果長の区別と左右差の解釈を扱う。"},{"name":"徒手筋力テストの代償動作","scope":"肩関節屈曲・股関節外転などの測定でみられる代償動作と、その原因となる筋を扱う。"},{"name":"徒手筋力テストの抵抗・触診と高段階の手技","scope":"段階4・5での抵抗のかけ方、段階1の触診による判定、筋の触知部位（ヒラメ筋など）を扱う。"},{"name":"徒手筋力テストの段階判定と検査肢位","scope":"Danielsらの段階の定義（段階3など）と、段階と測定肢位・開始肢位の組合せ、肢位保持からの段階推測を扱う。"},{"name":"徒手筋力テストの部位別手技","scope":"頸筋・体幹筋、手指筋、肩甲下筋など特定の筋のテスト方法と、図から対象筋を同定する問題を扱う。筋の分離評価を含む。"},{"name":"意識障害の評価（JCS・GCS）","scope":"症例の開眼・応答の様子からのJCS（Japan Coma Scale）の判定と、GCSの評定を扱う。"},{"name":"感覚検査と平衡機能障害の鑑別","scope":"深部感覚（位置覚・振動覚）の検査法と器具、Romberg徴候、後索性・小脳性・前庭性の平衡機能障害の鑑別を扱う。"},{"name":"末梢神経・脳神経障害の評価","scope":"末梢神経麻痺と特徴的所見の対応、顔面神経の評価、神経伝導検査の適応、運動障害と評価方法の対応を扱う。"},{"name":"栄養・代謝と臨床検査値の評価","scope":"栄養状態の評価指標、BMIの計算と糖尿病の体重管理、腎機能・糖尿病合併症・深部静脈血栓症などで優先すべき検査項目を扱う。"},{"name":"歩行補助具の適合","scope":"杖の長さ調整とチェックアウト、松葉杖の一般的な設定を扱う。"},{"name":"注意・記憶の評価","scope":"注意障害の検査（Trail Making Testなど）と、RBMT・数字順唱など記憶の分類に応じた評価法を扱う。"},{"name":"疼痛評価尺度","scope":"NRS・VASなど疼痛の評価に用いられる尺度と、その特徴・測定尺度の水準を扱う。"},{"name":"病的反射・錐体路徴候の検査","scope":"病的反射の誘発方法・刺激部位と反射名の対応を扱う。"},{"name":"移動能力・運動耐容能の評価","scope":"Timed Up and Go Testと6分間歩行テストの方法、全身持久性評価の選択、転倒リスクとの関連を扱う。"},{"name":"筋力の定量的評価とMRC sum score","scope":"等尺性筋力測定によるトルク計算と、MRC sum scoreによるICU-AWの評価・判定を扱う。Danielsらの段階判定は含まない。"},{"name":"筋短縮・柔軟性の整形外科的テストと股・足部","scope":"Thomas・Ely・Oberテストなど筋短縮の検査、二関節筋短縮による可動域制限、足根管症候群のTinel徴候、股関節脱臼の所見、足関節靱帯の検査を扱う。"},{"name":"筋緊張の評価（modified Ashworth scale）","scope":"他動運動時の抵抗感に基づくmodified Ashworth scaleの段階判定を扱う。"},{"name":"筋電図・電気生理学的検査とALS","scope":"筋萎縮性側索硬化症における針筋電図・反復刺激試験の所見と、診断に有用な電気生理学的検査を扱う。"},{"name":"肩の整形外科的テストと腱板・上腕二頭筋腱の所見","scope":"腱板損傷・上腕二頭筋長頭腱炎の検査、胸郭出口症候群の誘発テスト、翼状肩甲など肩周囲の所見の同定を扱う。"},{"name":"肩関節の関節可動域測定法","scope":"1995年基準に従う肩関節外転などの測定手順と、図示された肩関節測定の正誤を扱う。肩以外の関節は含まない。"},{"name":"脊柱・神経根の整形外科的テスト","scope":"腰椎椎間板ヘルニアで陽性となる神経根伸張・疼痛誘発テストと、Spurlingテストなど頸部神経根の検査を扱う。"},{"name":"脊髄損傷の神経学的評価（ASIA）","scope":"AISの判定、髄節とkey muscle・感覚検査ポイントの対応、運動レベル・神経学的レベルと仙髄機能温存を扱う。頸髄損傷のZancolli分類も含む。"},{"name":"脳卒中の評価スケールとNIHSS","scope":"NIHSSをはじめとする脳卒中の評価法と、含まれる項目の組合せ・各評価法の特徴を扱う。SIAS単独の評定は含まない。"},{"name":"脳性麻痺の粗大運動評価（GMFM・GMFCS）","scope":"GMFMの構成、GMFCSのレベル分類、脳性麻痺で残存しやすい原始反射を扱う。"},{"name":"膝の整形外科的テスト（半月板・靱帯）","scope":"McMurrayテストなど半月板損傷の検査と、前後引き出しテストなど靱帯安定性テストの対象を扱う。"},{"name":"評価の進め方と記録（SOAP・POMR）","scope":"SOAPの記載区分、情報収集における社会的情報と身体情報の分類、評価の統合・解釈、検査の診断精度（感度・特異度）を扱う。"},{"name":"認知機能スクリーニング検査","scope":"HDS-R・MMSEの構成項目と違い、認知症のスクリーニング検査、語の流暢性課題を含む検査を扱う。"},{"name":"運動失調の評価","scope":"脊髄小脳変性症の運動失調を評価する尺度と、過回内など小脳性運動失調の所見を扱う。"},{"name":"長期臥床の影響と褥瘡","scope":"安静臥床による廃用と循環・呼吸への影響、体位別の褥瘡好発部位を扱う。"},{"name":"関節リウマチ・変形性関節症の評価と分類","scope":"Steinbrocker分類など関節リウマチの機能分類、Heberden結節など変形性関節症の所見、関節保護のADL指導を扱う。"},{"name":"関節可動域の参考可動域角度","scope":"運動方向と参考可動域角度の組合せを扱う（股関節・足部の角度を含む）。軸や測定手順は扱わない。"},{"name":"関節可動域測定の基本軸・移動軸（上肢・手指）","scope":"肩・前腕・手関節・手指と母指の運動について、基準による基本軸・移動軸の組合せを扱う。下肢・体幹の軸は含まない。"},{"name":"関節可動域測定の基本軸・移動軸（下肢・足部）","scope":"股・膝・足部（内がえし・外がえしを含む）の基本軸・移動軸と、下肢の関節可動域測定法の原則を扱う。"},{"name":"関節可動域測定の基本軸・移動軸（体幹・頸部）と運動面","scope":"胸腰部回旋など体幹・頸部の基本軸・移動軸と、矢状面・前額面など角度を測定する運動面の分類を扱う。"},{"name":"関節可動域測定の測定肢位・代償運動と最終域感","scope":"運動方向と測定肢位の組合せ、測定時に生じる代償運動、正常な最終域感（end feel）を扱う。"},{"name":"高次脳機能検査の使い分け","scope":"失行（観念運動失行など）・遂行機能（WCST）・半側空間無視（BIT）・前頭葉機能の検査と、障害との組合せを扱う。"},{"name":"うつ病と双極性障害の症状・比較","scope":"無価値感・思考制止・心気妄想などうつ病の症状と、発症年齢・遺伝要因（一卵性双生児の一致率）・経過における双極性障害との違い、好発年齢を扱う。支援や対応の進め方は含まない。"},{"name":"うつ病の自殺予防と復職支援","scope":"自殺の危険因子と危険の高い患者の特徴、および復職支援・リワークプログラムの位置づけと内容を扱う。うつ病の症状そのものの判別は含まない。"},{"name":"せん妄と器質性精神障害","scope":"せん妄の特徴と危険因子、器質性精神障害の急性期症状と性質を扱う。認知症の中核症状・BPSDそのものは含まない。"},{"name":"てんかん・発達障害に伴う精神症状","scope":"ミオクロニー発作などのてんかんの発作型とてんかんに伴う精神症状、自閉スペクトラム症の特徴、注意欠如・多動性障害（ADHD）の評価と注意点を扱う。"},{"name":"アルコール・薬物依存と離脱症状","scope":"アルコール離脱せん妄・振戦せん妄の時期と治療、離脱けいれん、Korsakoff症候群、断酒継続の支援、共依存・イネイブラー、およびベンゾジアゼピン系薬の依存と離脱を扱う。"},{"name":"パーソナリティ障害の分類と特徴","scope":"境界性パーソナリティ障害の見捨てられ不安、統合失調型などクラスターAの特徴、各障害の性差といった、パーソナリティ障害の分類と症候の対応を扱う。"},{"name":"不安・強迫・適応障害の症状と治療","scope":"強迫性障害の症状・病識と曝露反応妨害法、全般性不安障害、パニック障害の薬物療法、適応障害の診断と治療の原則を扱う。曝露の原理そのもの（条件付け）は学習理論の論点に寄せる。"},{"name":"主な心理療法と創始者・特徴","scope":"来談者中心療法・森田療法・自律訓練法・社会生活技能訓練（SST）など、心理療法や技法とその創始者・代表的人物・決定的な特徴の対応を扱う。精神分析と認知行動療法の内部の概念は含まない。"},{"name":"加齢に伴う心理変化と老年期の精神保健","scope":"結晶性知能と流動性知能など加齢で保たれる・低下する精神機能の区別と、老年期の社会的孤立など精神保健上の問題、成人期後期の特徴を扱う。認知症そのものの症状は含まない。"},{"name":"地域精神保健とACT・社会復帰支援","scope":"ACT（包括型地域生活支援）の体制と訪問の特徴、およびSF-36など健康関連QOLの測定を含む社会復帰・地域生活の評価と支援を扱う。家族への心理教育は統合失調症の家族支援の論点に寄せる。"},{"name":"学習理論に基づく行動療法の技法","scope":"古典的・オペラント条件付け、モデリング（観察学習）、系統的脱感作、バイオフィードバックなど学習理論に基づく技法と、Banduraの自己効力感を扱う。認知の歪みを扱う技法は含まない。"},{"name":"心理検査の分類と代表的検査","scope":"投影法（ロールシャッハ・TAT・SCT・P-Fスタディ）、質問紙法（MMPI・YG・BDI-IIなど）、作業検査法（内田クレペリン）といった分類と、各検査が何を評価するかを扱う。"},{"name":"患者への対応とコミュニケーション・心理教育","scope":"リエゾン精神医学でのベッドサイドマナー、うつ病患者への病気の説明と心理教育、認知症患者の訴えへの共感的な応答など、患者への関わり方そのものを扱う。具体的な治療技法の判別は含まない。"},{"name":"慢性疼痛の認知行動療法","scope":"慢性腰痛など慢性疼痛に対する認知行動療法の進め方と、恐怖回避モデルに基づく誤った対応（痛みの確認の繰り返しなど）を扱う。一般の認知行動療法の技法判別は含まない。"},{"name":"摂食障害の特徴と身体合併症","scope":"神経性無食欲症と神経性大食症の有病率・病識・ボディイメージ・代償行動の違いと、無月経や高コレステロール血症などの身体所見・合併症を扱う。"},{"name":"発達段階と発達課題（Freud・Erikson）","scope":"Freudの心理性的発達段階（口唇期・肛門期・男根期・潜在期など）と、Eriksonの心理社会的発達段階・発達課題（成人中期の生殖性、老年期の統合など）の年齢との対応を扱う。"},{"name":"睡眠障害の分類と睡眠指導","scope":"睡眠相後退症候群などの概日リズム睡眠・覚醒障害、レム睡眠行動障害、ナルコレプシー、レム・ノンレム睡眠の生理と、睡眠衛生指導・睡眠日誌の使い方を扱う。"},{"name":"精神分析療法と転移・逆転移","scope":"無意識の葛藤を洞察する精神分析療法の考え方と、治療場面での転移（陽性・陰性）・逆転移の意味を扱う。個々の防衛機制の判別は含まない。"},{"name":"統合失調症の予後と家族支援","scope":"発症誘因の有無や発症年齢など予後を左右する因子と、高EE（感情表出）・家族心理教育による再発予防を扱う。地域支援の体制そのものは含まない。"},{"name":"統合失調症の症状と病型","scope":"思考の障害（思考途絶など）、妄想気分などの陽性症状、意欲低下・感情平板化などの陰性症状、前駆期の症状、緊張型などの病型を扱う。経過や予後の判断は含まない。"},{"name":"解離性障害と機能性神経学的症状症","scope":"解離性障害への説明と治療の進め方、離人症状、機能性神経学的症状症（変換症）の特徴と予後を扱う。身体疾患としての神経症状の鑑別は含まない。"},{"name":"記憶の分類と過程","scope":"記銘・保持・想起の過程と、即時記憶・ワーキングメモリー・手続き記憶・陳述記憶・展望記憶などの分類、および記憶と関係する脳部位を扱う。心理検査としての記憶評価の判別は検査の論点に寄せる。"},{"name":"認知症の症状（中核症状・BPSD）とケア","scope":"認知症の中核症状と周辺症状（BPSD）の区別と、音楽療法・リアリティオリエンテーションなどの非薬物療法を扱う。せん妄との区別や器質性精神障害の総論は含まない。"},{"name":"認知行動療法の技法と認知の歪み","scope":"認知再構成法とコラム表、自動思考と認知の歪み（極端な一般化など）、宿題や模擬場面のリハーサルといった認知行動療法の進め方を扱う。慢性疼痛に特化した問題は含まない。"},{"name":"防衛機制の種類と区別","scope":"投影・反動形成・昇華・知性化・抑圧と抑制など、防衛機制の名称と具体例の対応を扱う。転移そのものは防衛機制ではない、といった区別も含む。"},{"name":"障害受容の過程と段階に応じた対応","scope":"障害受容の5つの過程（ショック期・否認期・混乱期・解決への努力期・受容期）の順序と、各段階、とくに抑うつ状態の時期への対応の適否を扱う。"},{"name":"ADLの概念と自助具・介助","scope":"ADLの定義・概念（環境要因の影響を含む）と、疾患に応じた自助具の選択、視覚障害者の手引き歩行などの移動介助の方法を扱う。ADL評価尺度の採点手順は含まない。"},{"name":"ICFの構成要素と活動・参加・環境因子","scope":"心身機能・身体構造・活動・参加・環境因子・個人因子のどこに当たるかの判別と、各構成要素に含まれる内容を扱う。評価点の意味は「ICFの評価点」で、コアセットは別の論点で扱う。"},{"name":"ICFの評価点","scope":"心身機能・身体構造・活動と参加・環境因子それぞれの第一・第二評価点が何を示すか（実行状況と能力、促進・阻害の符号など）を扱う。構成要素そのものの判別は含まない。"},{"name":"ICFコアセットとWHO国際分類","scope":"疾患別コアセット（脳卒中Brief core setなど）の内容・種類と、ICD・ICIDHなどWHO国際分類ファミリーの中でのICFの位置付け、倫理的ガイドラインなどのICF総論的事項を扱う。"},{"name":"チーム医療と多職種連携・診療記録","scope":"カンファレンスでのコンフリクトへの対応などチームの連携の進め方、理学療法士の業務範囲と他職種への相談、およびSOAP・POMRによる診療記録の記載を扱う。"},{"name":"フレイルとロコモーティブシンドローム","scope":"フレイルの特徴（身体的フレイルの判定基準を含む）とロコモーティブシンドロームの概念・特徴・要因を扱い、サルコペニアとの関係も含む。"},{"name":"廃用症候群と入院関連機能障害","scope":"安静臥床・術後に生じる廃用症候群の身体変化とその予防の組合せ、および入院に伴って生じる機能低下（HAD）の概念を扱う。フレイルそのものは含まない。"},{"name":"慢性疼痛・がん性疼痛への包括的対応","scope":"慢性疼痛とがん性疼痛について、要因が単一でないことや治療目標の置き方、多職種関与や精神的ケアを含むトータルペインとしての対応を扱う。鎮痛薬の薬理は含まない。"},{"name":"障害福祉の理念とリハビリテーションの歴史","scope":"ノーマライゼーション、自立生活（IL）運動、国際障害者年など障害観・福祉理念の内容と始まった年代の順序、および日本で理学療法士養成教育が始まった時期などの歴史的事項を扱う。"},{"name":"インフォームドコンセントと患者への対応","scope":"インフォームドコンセントの進め方と同意内容の文書保存、自己決定の保障に加え、難聴・認知症のある患者への情報収集や、服薬への不安の訴えに対する対応と他職種へのつなぎを扱う。"},{"name":"ケアプラン（居宅サービス計画）","scope":"ケアプラン第1表に記載される項目（総合的な援助の方針など）と、居宅介護支援が全額介護保険給付となる仕組みを扱う。"},{"name":"リハビリテーションのリスク管理と廃用予防","scope":"積極的なリハビリテーションを実施しない基準と運動療法の中止基準、気管吸引など処置時の安全確認、廃用症候群と周術期肺塞栓症の予防（早期離床を含む）を扱う。"},{"name":"一次救命処置とAED","scope":"成人の一次救命処置の手順（最初に意識を確認することなど）、胸骨圧迫の回数・テンポ、AEDの使用方法と電気的除細動の適応（心室細動・無脈性心室頻拍）を扱う。"},{"name":"人口動態統計と保健指標","scope":"死因の順位、自殺死亡率の高い年齢階級、要介護となった原因疾患など、人口動態統計や国民生活基礎調査で示される保健・介護の指標を扱う。"},{"name":"介護予防と基本チェックリスト","scope":"介護予防の二次予防事業における対象者決定、基本チェックリストの質問項目と低栄養の判定基準（BMI）を扱う。転倒予防講演会など一次予防一般は疾病予防の段階で扱う。"},{"name":"介護保険の被保険者と特定疾病","scope":"第1号・第2号被保険者の区分と加入年齢、特定疾病によって第2号被保険者が給付を受けられる条件、要支援者の介護予防サービスや事業者選択など、制度を利用する入口と原則を扱う。"},{"name":"住宅改修と住環境整備","scope":"介護保険の住宅改修で対象になる工事と対象外の工事（階段昇降機の設置など）、スロープ勾配などバリアフリーの基準、疾患特性に合わせた住環境整備を扱う。福祉用具の品目判定は扱わない。"},{"name":"保健医療の法規と診療報酬・地域保健","scope":"医療法で規定される事項の範囲、診療報酬の改定周期、法律とその規定内容の対応、地域保健法に基づく保健所の業務を扱う。理学療法士法そのものは別の論点で扱う。"},{"name":"個人情報と診療情報の保護・開示","scope":"個人情報保護法における個人情報の定義と医療機関での取扱い、診療記録の開示請求、住宅改修の相談など関係者との情報共有の可否を扱う。"},{"name":"健康増進法と生活習慣病・がん","scope":"生活習慣病に含まれる疾患の範囲、健康増進法に規定される生活習慣病の発症・重症化予防やがん検診、がんの発生要因を扱う。"},{"name":"労働衛生と作業環境・人間工学","scope":"作業関連疾患と労働衛生の考え方、産業理学療法における職業性腰痛の対策、作業姿勢の指導、VDT作業における人間工学的な配慮を扱う。"},{"name":"医療安全とインシデントレポート","scope":"Heinrichの法則、インシデントレポート収集の目的と報告しやすい環境づくりなど、医療事故を防ぐための考え方を扱う。転倒時など個別の事故への対応手順は扱わない。"},{"name":"地域包括ケアシステムと地域リハビリテーション","scope":"地域包括ケアシステムにおける自助・互助・共助・公助の区分と地域包括支援センターの配置職種、CBRマトリクスの領域と地域リハビリテーションの理念・取り組みを扱う。"},{"name":"急変・発作・転倒時の初期対応","scope":"訓練中の意識消失への初期対応、てんかんの複雑部分発作時の安全確保、歩行練習中の転倒時に優先する対応など、臨床現場の突発事象への初動を扱う。一次救命処置の手順そのものは扱わない。"},{"name":"感染経路別予防策と院内感染対策","scope":"接触感染など感染経路に応じた経路別予防策（MRSA対策を含む）と、病室の配置管理、室内空調の陽圧・陰圧など院内感染対策の体制と環境管理を扱う。"},{"name":"標準予防策と手指衛生","scope":"標準予防策の考え方、手指衛生が必要な場面とタイミング、使用後の手袋の廃棄など、すべての患者に適用する基本的な感染予防の実践を扱う。"},{"name":"災害リハビリテーションと支援チーム","scope":"災害リハビリテーション支援の活動時期と、被災者の生活機能を中心に支援するJRATなど災害時の支援チームの役割を扱う。DMATなど医療中心のチームとの違いもここで扱う。"},{"name":"理学療法士法と職業倫理・守秘義務","scope":"理学療法士及び作業療法士法が定める守秘義務・免許の取消し・名称独占、職業倫理の原則、臨床実習における守秘と情報管理を扱う。個人情報保護法の定義そのものは扱わない。"},{"name":"疾病予防の段階と予防接種","scope":"一次・二次・三次予防の区分と具体例（健康教育・ワクチン接種、検診・人間ドック、リハビリテーションや職場復帰支援）、および予防接種法に基づく定期接種の区分を扱う。"},{"name":"福祉用具貸与と特定福祉用具販売","scope":"福祉用具貸与の対象品目と特定福祉用具販売の対象品目の区別、要支援1など軽度者が給付対象となる品目と例外給付を扱う。住宅改修の対象判定は扱わない。"},{"name":"要介護認定の仕組み","scope":"要支援と要介護の違いを判定する状態の不安定性、介護認定審査会による要介護度の判定、主治医意見書など認定の手続きを扱う。被保険者の区分や給付の内容そのものは扱わない。"},{"name":"訪問・通所リハビリテーション","scope":"訪問リハビリテーションの目的や家族を含む目標設定、利用者ニーズ、通所リハビリテーションの目的など、介護保険におけるリハビリテーションサービスの特徴を扱う。"},{"name":"障害者福祉の理念と障害者総合支援法","scope":"ノーマライゼーションの成立と内容、障害者総合支援法への移行で追加された対象（難病）と、介護給付と訓練等給付の区分を扱う。"},{"name":"がんリハビリテーションと緩和ケア","scope":"がんリハビリテーションの時期分類（治療前・回復期・緩和期）と緩和ケア病棟での進め方、骨転移・病的骨折のリスクへの配慮を扱う。腫瘍そのものの病期・治療は臨床医学・病理側の論点とする。"},{"name":"バランス練習と転倒予防","scope":"バランス練習の難度設定（支持基底面・感覚条件の操作）と段階付け、転倒予防を目的とした理学療法を扱う。バランスの評価法（TUG・BBSなど）そのものは理学療法評価側の論点とする。"},{"name":"リンパ浮腫の複合的理学療法と生活指導","scope":"リンパ浮腫の病態の要点と、複合的理学療法（用手的リンパドレナージ・圧迫療法・圧迫下の運動・スキンケア）、乳癌術後を含む日常生活指導と蜂窩織炎の予防を扱う。浮腫一般の病態は臨床医学・病理の論点とする。"},{"name":"上肢・脊椎の運動器疾患の病態","scope":"de Quervain病・Kienböck病・上腕骨外側上顆炎・肘関節脱臼、腰椎変性すべり症・腰椎分離症、骨形成不全症など骨脆弱性を伴う疾患の病態と臨床像を、治療法選択の前提として扱う。治療手技そのものは含まず、病態の詳細は臨床医学・病理側の論点と重なる前提で最小限にとどめる。"},{"name":"下肢・股関節の運動器疾患の病態と徴候","scope":"Perthes病・特発性大腿骨頭壊死症・アキレス腱周囲炎の病態、大腿骨近位部骨折の分類、Trendelenburg徴候、高齢者の転倒による骨折など、下肢・股関節疾患の病態と徴候を治療法選択の前提として扱う。治療手技そのものは含まず、病態の詳細は臨床医学・病理側の論点と重なる前提で最小限にとどめる。"},{"name":"変形性股関節症と人工股関節術後の理学療法","scope":"変形性股関節症の保存期のADL指導（杖・階段昇降を含む）と、後方進入法による人工股関節置換術・人工骨頭置換術後の脱臼予防肢位、荷重と運動の進め方、術後神経麻痺への電気刺激などの対応を扱う。"},{"name":"変形性膝関節症の理学療法と術後療法","scope":"変形性膝関節症に対するガイドライン推奨の介入と関節拘縮への対応、高位脛骨骨切り術・人工膝関節置換術（CPMを含む）など術後の理学療法を扱う。病態の進行そのものは一部この論点に含むが、病理的な変化の詳細は臨床医学・病理側と重なる。"},{"name":"廃用症候群とサルコペニアへの運動療法","scope":"廃用症候群の病態と分類、サルコペニア（加齢による筋萎縮を含む）に対する理学療法・運動療法を扱う。フレイル・サルコペニアの評価基準は理学療法評価・臨床医学側の論点とする。"},{"name":"摂食嚥下障害への対応と訓練","scope":"摂食嚥下障害への対応の原則、Shaker法などの嚥下訓練手技の区別、嚥下障害時の栄養管理（経腸栄養を含む）を扱う。嚥下の生理や嚥下評価・検査は生理学・理学療法評価側の論点とする。"},{"name":"水治療法と水中運動","scope":"水の物理的特性（浮力・粘性・静水圧）と水中運動療法の生理作用、水深による免荷率、渦流浴の適応、小児への深部温熱など対象別の禁忌を扱う。"},{"name":"温熱・寒冷療法の作用と適否","scope":"温熱療法の生理学的作用・局所反応と熱伝達様式、禁忌（脱髄疾患のUhthoff現象など）、寒冷療法の作用と痙縮低下の機序、極超短波の照射強度（逆二乗・余弦の法則）による計算を扱う。深部温熱としての極超短波はこの論点に含める。"},{"name":"熱傷の理学療法","scope":"熱傷後の良肢位と植皮後の安静・運動制限、熱傷後瘢痕拘縮に対する圧迫療法・関節可動域練習・装具療法を扱う。熱傷の病態・深度分類は臨床医学・病理側の論点とする。"},{"name":"神経筋再教育と運動失調・神経筋疾患へのアプローチ","scope":"神経筋再教育の概念と適応、Frenkel体操やPNFによる運動失調へのアプローチ、多発性筋炎・重症筋無力症など神経筋疾患で運動療法を行う際の負荷量と注意点を扱う。疾患の病態そのものは臨床医学・病理側の論点とする。"},{"name":"筋力増強運動と収縮様式・運動連鎖","scope":"筋力増強運動の原則と効果、等尺性・等張性・等速性などの収縮様式、開放性・閉鎖性運動連鎖、抵抗運動の対象筋と方向の組合せ、骨盤底筋群の筋力増強を扱う。収縮の生理機構そのものは生理学側の論点とし、ここでは運動の組み立て方に寄せる。"},{"name":"肩関節・回旋筋腱板の運動療法","scope":"回旋筋腱板を対象とした筋力増強運動（ゴムバンド外旋など）と腱板損傷術後のトレーニング、肩関節のストレッチングで伸張される筋を扱う。腱板の整形外科的テストは理学療法評価側、筋の作用そのものは運動学側の論点とする。"},{"name":"腰痛・腰椎疾患の保存療法と生活指導","scope":"慢性腰痛に対するガイドライン推奨の介入、腰椎椎間板ヘルニア・腰椎変性すべり症・脊柱管狭窄症の保存療法後の理学療法と姿勢・生活指導、Williams型装具などの装具の適応を扱う。腰椎疾患の症候・手術適応そのものは病態側の論点に寄せる。"},{"name":"膝靱帯損傷の予防と理学療法","scope":"前十字靱帯損傷の予防指導と神経筋トレーニング、損傷後の理学療法、再建術後の段階的な進め方を扱う。靱帯の整形外科的テスト（ラックマンなど）は理学療法評価側の論点とする。"},{"name":"褥瘡予防と体位管理","scope":"褥瘡の危険因子と予防、体位変換とポジショニングによる除圧を扱う。褥瘡の病期分類や創傷治癒の病態は臨床医学・病理側の論点とする。"},{"name":"超音波療法の適応・照射条件と禁忌","scope":"超音波療法の周波数と深達度、強度・時間率などの照射条件、ビーム不均等率と導子の操作、適応と禁忌（金属・骨癒合促進目的の低出力パルス超音波を含む）を扱う。"},{"name":"軟部組織損傷の急性期対応と回復期リハビリテーション","scope":"足関節外側靱帯損傷や肉離れなどの急性軟部組織損傷に対するRICE/POLICE処置と物理療法の適否、固定後のリハビリテーションの進め方、再発予防の筋力増強を扱う。"},{"name":"運動療法の原則と対象別の対応","scope":"運動療法の一般原則（適応・負荷・進め方）と、認知症患者など対象の特性に応じた運動療法時の対応を扱う。個別疾患に特化した運動処方は各疾患別の論点とする。"},{"name":"関節リウマチの理学療法と関節保護","scope":"関節リウマチに対する運動療法の進め方、関節保護の生活指導、環軸関節亜脱臼など頸椎病変がある場合の運動の禁忌を扱う。関節リウマチの病態・薬物療法は臨床医学・病理側の論点とする。"},{"name":"関節可動域運動とストレッチング","scope":"関節可動域運動の目的と進め方、二関節筋の能動的不足を踏まえた選択的伸張肢位、関節可動域改善を目的とする体操法を扱う。可動域の測定法は理学療法評価側、筋の作用そのものは運動学側の論点とする。"},{"name":"骨折術後の理学療法と運動開始の原則","scope":"各種骨折（踵骨・脛骨高原・鎖骨・下腿・膝蓋骨・大腿骨転子部、小児の上腕骨顆上骨折、頸椎骨折など）の術後・固定後における運動開始時期、荷重の段階付け、関節可動域練習の進め方と合併症への注意を扱う。骨折の分類・画像読影そのものは病態側の論点とする。"},{"name":"Guillain-Barré症候群の臨床像と急性期管理","scope":"病型（脱髄型・軸索型）と経過、人工呼吸管理下での体位排痰・胸郭ストレッチなど急性期の理学療法、障害スコアによる歩行予後の予測を扱う。"},{"name":"Parkinson病の重症度分類と歩行障害への対応","scope":"Hoehn & Yahrの重症度分類による症例のステージ判定と、すくみ足・突進現象・小刻み歩行に対する床の目印や聴覚刺激などの外的キューイングを用いた歩行指導を扱う。"},{"name":"くも膜下出血の臨床像と続発症","scope":"くも膜下出血の症状（項部硬直など）と頭部CT所見、続発する交通性水頭症と正常圧水頭症の三主徴を扱う。"},{"name":"パーキンソン症候群と類縁疾患の鑑別","scope":"進行性核上性麻痺の臨床像（垂直性眼球運動障害・易転倒性など）、Huntington病など遺伝性の神経変性疾患、Parkinson病との鑑別点を扱う。"},{"name":"プッシャー現象と姿勢垂直の障害","scope":"プッシャー（押し）現象と側方突進の病態・病変部位、姿勢垂直の障害による立位姿勢の偏位と、鏡など視覚フィードバックや麻痺側荷重を用いた対応を扱う。"},{"name":"半側空間無視の評価と理学療法","scope":"線分抹消試験など評価の選択と優先順位、プリズム適応・頸部振動刺激を含むアプローチ、車椅子操作など日常生活での配慮を扱う。"},{"name":"多発性硬化症の臨床像と理学療法","scope":"再発と寛解を繰り返す経過と疫学、Uhthoff現象による温熱・運動時の注意、寛解期の理学療法と禁忌、視神経脊髄炎など関連する脱髄疾患を扱う。"},{"name":"失行の分類と道具使用への影響","scope":"観念失行・観念運動失行・肢節運動失行の鑑別と、スプーン操作や歯磨きなど道具使用・食事動作に現れる症状を扱う。"},{"name":"失語症の分類とコミュニケーション支援","scope":"Broca失語など失語症の型と症状（流暢性・理解など）の対応と、失語患者への質問の仕方・意思伝達手段の配慮を扱う。"},{"name":"失調・平衡障害に対する理学療法","scope":"Frenkel体操、重錘負荷、rhythmic stabilization、バランス練習の段階づけ、失調患者の歩行補助具の選択、感覚性失調への固有感覚・視覚代償の利用、BPPVに対するEpley法など、失調と平衡・めまい障害への訓練法を扱う。"},{"name":"末梢神経障害の所見と電気診断","scope":"糖尿病性多発ニューロパチーの靴下型感覚障害、頸椎神経根症と髄節の対応、後根障害と前根障害の鑑別（腱反射など）、神経伝導検査の波形から脱髄と軸索変性を読み取る問題を扱う。"},{"name":"片麻痺のADL指導と移乗・環境設定","scope":"更衣・入浴・起き上がり・階段などADL指導の原則、車椅子とベッド・床との移乗の手順と介助、ポータブルトイレの配置など生活環境の設定を扱う。脊髄損傷者の移乗は機能残存レベルの論点で扱う。"},{"name":"片麻痺の歩行練習と歩行自立の見通し","scope":"トレッドミル歩行練習などの歩行練習法、障害物をまたぐなどの応用歩行、退院時歩行目標の設定に必要な情報、歩行自立と関連する因子、異常歩行と原因疾患の対応を扱う。"},{"name":"片麻痺の痙縮・共同運動と回復パターン","scope":"Brunnstromステージと共同運動パターン、Wernicke-Mann肢位、連合反応（Strümpell現象など）、痙縮の分布とボツリヌス療法を含む痙性への対応、反張膝への対応を扱う。"},{"name":"神経疾患の評価尺度（FIM・TUG・SARA・QMG）","scope":"FIMの採点（歩行の距離条件・食事など）、TUGによる転倒リスク・移動能力の評価、運動失調のSARA、重症筋無力症のQMG scoreなど、神経疾患で用いる尺度の使い分けと採点を扱う。意識レベルの尺度は急性期の論点で扱う。"},{"name":"神経筋疾患の理学療法と過用への配慮","scope":"重症筋無力症やDuchenne型筋ジストロフィーなど神経筋疾患別の理学療法の原則、過用性筋力低下（オーバーワーク）を避ける負荷設定、筋ジストロフィーのステージに応じた装具・評価の優先度を扱う。"},{"name":"筋ジストロフィーの臨床像と経過","scope":"Duchenne型の経過とGowers徴候、筋強直性ジストロフィーのミオトニアと多系統の臨床像、福山型など型別の発症年齢を扱う。理学療法の進め方は神経筋疾患の理学療法の論点で扱う。"},{"name":"筋萎縮性側索硬化症の臨床像と対応","scope":"ALSで生じにくい症状（眼球運動障害など）を含む臨床像と、BFO・プラスチックAFOなど病状の進行に応じた補助具・装具の導入を扱う。"},{"name":"肩手症候群・CRPSへの対応","scope":"脳卒中後の肩手症候群（複合性局所疼痛症候群 typeⅠ）の分類と病態、急性期の理学療法（肩関節周囲筋の再教育など）を扱う。"},{"name":"脊髄損傷のレベル判定と評価（ASIA・Zancolli）","scope":"ASIA（ISNCSCI）の評価法と感覚検査ポイント、Zancolliの四肢麻痺上肢機能分類、キーマッスルやMMT・観察した動作からの機能残存レベルの判定を扱う。到達動作との対応は別の論点とする。"},{"name":"脊髄損傷の合併症と二次障害の予防","scope":"自律神経過反射の症候と発症時の対応、褥瘡の好発部位と除圧、中心性脊髄損傷などの損傷型、立位・歩行練習による二次障害予防の目的を扱う。"},{"name":"脊髄損傷の機能残存レベルと到達動作","scope":"機能残存レベルと、移乗・更衣・起き上がり・プッシュアップ・装具歩行など到達可能な動作との対応を扱う。レベル判定の方法そのもの（ASIAの検査手順など）は別の論点とする。"},{"name":"脳卒中の画像診断と血管病変","scope":"脳梗塞の拡散強調像など発症時期による画像所見、脳出血の好発部位とCT読影、もやもや病の脳血管造影所見を扱う。"},{"name":"脳卒中急性期の離床と理学療法","scope":"急性期の離床開始・中止の判断基準、意識レベル（JCS・GCS）やバイタルによる可否の判定、神経症候の増悪がない場合の早期離床の進め方を扱う。"},{"name":"脳神経の機能と障害の鑑別","scope":"顔面神経・三叉神経など脳神経の支配領域と検査法、眼球運動の観察から外転神経など障害されている脳神経を同定する問題を扱う。"},{"name":"認知症と認知障害を伴う疾患","scope":"認知症の型別症状（前頭側頭型・Lewy小体型・血管性など）、軽度認知障害（MCI）の疫学、神経線維腫症など知的障害を伴う症候群の特徴的所見を扱う。"},{"name":"運動失調の鑑別と神経徴候の検査","scope":"小脳性と感覚性（脊髄性）運動失調の鑑別、Romberg徴候、反復拮抗運動などの協調運動検査、Lasègue・Lhermitteなどの神経徴候、亜急性連合性脊髄変性症など後索障害の原因疾患を扱う。"},{"name":"高次脳機能障害の病巣対応と動作指導","scope":"大脳の部位（前頭葉・頭頂葉・線条体・海馬など）と出現する症候の対応、遂行機能障害や記憶障害に対する手順確認・エラーレスラーニングなどの動作指導を扱う。失行・失語・半側空間無視は各論点で扱う。"},{"name":"人工呼吸管理中の理学療法と合併症","scope":"人工呼吸器（侵襲的・非侵襲的）管理中の患者への理学療法と二次的合併症の予防、人工呼吸器関連肺炎（VAP）などの合併症、波形・肺コンプライアンスの変化の読み取り、神経筋疾患での非侵襲的陽圧換気（NPPV）導入の目安を扱う。"},{"name":"全身持久力トレーニングの効果","scope":"継続的な全身持久力・有酸素運動で起こる一般的な身体の適応（中性脂肪や安静時心拍数など、低下・増加する項目の判定）を扱う。特定の疾患への運動療法の効果は各疾患の論点に置く。"},{"name":"呼吸リハビリテーションと呼吸困難の生活指導","scope":"COPD・呼吸不全患者への呼吸リハビリテーションとして、口すぼめ呼吸の適応と指導方法、ADLで息切れを生じやすい動作と呼吸困難を減らす生活指導、在宅酸素療法中の療養指導、呼吸困難に応じた運動の進め方を扱う。"},{"name":"呼吸器疾患の病態と検査所見","scope":"COPDを中心に、閉塞性換気障害の肺機能・フローボリューム曲線・肺拡散能、身体所見と胸部画像所見を扱う。気管支喘息の気道可逆性と、高齢者肺炎・誤嚥性肺炎の特徴も含む。理学療法の手技・指導は呼吸リハビリテーションの論点に置く。"},{"name":"心不全の症候と重症度評価","scope":"左心不全と右心不全の症候の違い、うっ血所見、NYHA分類による重症度評価と、心不全患者の面接・離床開始時に確認する症状を扱う。"},{"name":"心臓リハビリテーションと心疾患の運動療法","scope":"心筋梗塞・虚血性心疾患・慢性心不全・弁膜症術後（TAVIを含む）に対する運動療法の進め方と効果（再入院の低下、脂質代謝や運動耐容能への効果、インターバルトレーニングを含む）を扱う。疾患そのものの病態・診断は臨床医学側とし、ここでは理学療法の実施と効果に限る。"},{"name":"心電図の判読と不整脈","scope":"不整脈（房室ブロック・心房細動・期外収縮・心房粗動など）の波形判読、QT間隔に影響する治療、運動負荷中のST変化、除細動の適応となる致死的不整脈を扱う。刺激伝導系の仕組みそのものは生理学の論点とする。"},{"name":"慢性腎臓病・透析患者の運動療法","scope":"慢性腎臓病の重症度（血清クレアチニンと筋量の関係を含む）と運動療法の進め方、血液透析患者への運動療法を扱う。透析患者の運動耐容能の評価法そのものは運動負荷試験の論点に置く。"},{"name":"末梢動脈疾患の評価と運動療法","scope":"閉塞性動脈硬化症・末梢動脈疾患の症状と好発部位、足関節上腕血圧比（ABI）などの検査、Fontaine分類と間欠性跛行に対する歩行運動療法、運動療法前に集めるべき医学情報を扱う。"},{"name":"気道クリアランスと吸引・排痰手技","scope":"気管吸引（開放式・気管切開患者）の手技と安全管理、体位排痰法と肺区域の対応、ハフィングなど排痰手技の選択を扱う。胸水貯留時など、貯留部位に応じた手技の選び方を含む。"},{"name":"糖尿病の症状・合併症と足病変","scope":"高血糖・低血糖の症状の判別と、糖尿病足病変・末梢神経障害に対するフットケア・免荷を扱う。ケトアシドーシスの酸塩基の解釈は血液ガスの論点に置く。"},{"name":"糖尿病の運動療法と安全管理","scope":"糖尿病患者への運動療法の効果、処方の組み立て、適応と中止の判断を扱う。腎症・網膜症などの合併症や血液透析併用がある場合の注意と、低血糖への備えを含む。"},{"name":"虚血性心疾患の鑑別と急性期の検査","scope":"狭心症と心筋梗塞の鑑別・特徴と、急性心筋梗塞が疑われる場面での検査の優先順位を扱う。病態の詳細は臨床医学・病理と重なるため、ここでは急性期の判断に必要な範囲に限る。"},{"name":"血液ガスの解釈と酸塩基平衡","scope":"動脈血ガス分析の読み取りと酸塩基平衡異常の判別、代謝性アシドーシスに対する呼吸性代償（糖尿病性ケトアシドーシスのKussmaul呼吸を含む）を扱う。生理学の呼吸調節そのものとは、検査値の解釈で区別する。"},{"name":"運動強度の設定と運動処方","scope":"Karvonen法・Borg指数・METs換算・ATに基づく強度設定、二重積と心筋酸素消費量、身体活動基準、薬剤服用下（β遮断薬など）での強度指標の選び方と運動時の血圧応答を扱う。強度への生体応答そのもの（運動学・生理学）とは、処方への使い方で区別する。"},{"name":"運動療法の開始・中止基準とリスク管理","scope":"内部障害全般の運動療法について、開始してよい状態・中止すべき状態・禁忌の判定と、大動脈解離などガイドラインに基づく開始基準（バイタルサインや鎮静レベルとの組合せ）を扱う。疾患固有の中止判断は各疾患の論点にも現れる。"},{"name":"運動負荷試験と運動耐容能の評価","scope":"運動負荷試験の種類（固定負荷・ランプ負荷など）、心肺運動負荷試験の指標と嫌気性代謝閾値（AT）の判定、最大酸素摂取量の読み取り、6分間歩行テストを含む運動耐容能の評価法とその対象の選び方を扱う。"},{"name":"酸素療法と体位による換気血流の改善","scope":"酸素療法機器の分類と選択、腹臥位など体位変換による換気血流比・酸素化の改善の仕組みと、急性呼吸不全での適用を扱う。"},{"name":"間質性肺疾患と拘束性換気障害","scope":"特発性肺線維症など間質性肺疾患の臨床像と理学療法（吸気筋トレーニング、労作時の呼吸困難・低酸素への対応）、拘束性換気障害の検査解釈、頸髄損傷に伴う呼吸障害を扱う。"},{"name":"集中治療・周術期の早期リハビリテーション","scope":"ICU入室中・術後急性期の患者への早期離床の可否判断（平均動脈圧・鎮静・疼痛など）と進め方、術前からの咳嗽練習を含む周術期の呼吸器合併症予防、急性期の栄養管理の基礎を扱う。人工呼吸器そのものの管理は人工呼吸管理の論点に置く。"},{"name":"Down症候群の特徴と理学療法","scope":"Down症候群の身体特徴と筋緊張低下による姿勢（蛙肢位など）、運動発達の特徴、乳幼児期の理学療法と家族指導、環軸関節不安定性などの二次障害を扱う。染色体異常全般の分類は含まない。"},{"name":"Duchenne型筋ジストロフィーの病期と管理","scope":"Duchenne型筋ジストロフィーの機能障害度ステージと病期に応じた移動能力、および呼吸管理（舌咽呼吸・咳介助を含む）を扱う。他の筋疾患は含まない。"},{"name":"GMFCSによる脳性麻痺の重症度と移動能力","scope":"GMFCS（E&Rを含む）のレベル分類と、各レベルで可能な移動・動作能力（歩行補助具や車椅子の使用を含む）の対応を扱う。レベル判定を問う問題が中心で、具体的な治療方針は含まない。"},{"name":"NICUと低出生体重児への発達支援","scope":"NICU・低出生体重児に対する生理的屈曲位を保つポジショニング、低緊張児への早期介入の優先順位など、入院早期の発達支援としての理学療法を扱う。"},{"name":"二分脊椎の機能残存レベルと合併症","scope":"二分脊椎の病型、Sharrard分類による機能残存レベルと残存筋・装具・歩行様式の対応、残存レベルに応じた筋力増強の優先順位、および水頭症・脊髄係留症候群などの合併症を扱う。"},{"name":"原始反射の出現・消失と中枢","scope":"原始反射・緊張性反射がいつ現れいつ消失するか、各反射を誘発する刺激と運動の組合せ、反射・反応の中枢の階層（脊髄・中脳など）、および発達検査における獲得時期の目安を扱う。反射が姿勢や動作にどう影響するかは「姿勢反応と原始反射の残存」で扱う。"},{"name":"姿勢反応と原始反射の残存","scope":"パラシュート反応（保護伸展反応）や立ち直り反応などの姿勢反応の出現順序と、非対称性緊張性頸反射・緊張性迷路反射など原始反射の残存が脳性麻痺児の姿勢・起き上がりに与える影響を扱う。出現・消失時期そのものの暗記問題は含まない。"},{"name":"小児の股関節疾患と骨形成不全症","scope":"発育性股関節形成不全（臼蓋角などのX線計測、リーメンビューゲル装具などの対応）とPerthes病（鑑別と免荷を中心とした理学療法）を中心に、コラーゲン異常による骨形成不全症の特徴も扱う。"},{"name":"心理・認知発達の段階","scope":"Piagetの認知発達段階、Eriksonの心理社会的発達段階（学童期・成人前期の課題など）、および思春期の心理発達と第二次性徴を扱う。発達検査による評価は含まない。"},{"name":"痙直型脳性麻痺の徴候と理学療法","scope":"痙直型脳性麻痺の陽性・陰性徴候と、痙直型両麻痺・四肢麻痺・片麻痺に対する理学療法、動作指導、遊びを通した指導を扱う。座位保持装置や車椅子の設定そのものは含まない。"},{"name":"発達検査・スクリーニング検査","scope":"JDDST-R（デンバー式）や遠城寺式乳幼児分析的発達検査など発達検査・スクリーニングの領域構成と項目の通過時期、および発達検査と知能検査（WISCなど）の区別を扱う。検査を通して問われるマイルストーンの時期もここに含める。"},{"name":"知的障害の原因疾患と染色体・代謝異常","scope":"知的障害の原因となる疾患の鑑別を扱い、性染色体異常などの染色体異常、フェニルケトン尿症などの先天性代謝異常を含む。Down症候群そのものの特徴・療法は含まない。"},{"name":"粗大運動・ADLの評価尺度（GMFM・WeeFIM・PEDI）","scope":"GMFM（GMFM-88とGMFM-66の違いを含む）、WeeFIM、PEDIなど、小児の粗大運動能力とADLを測る評価尺度の構成・対象・特徴を扱う。GMFCSによる重症度分類そのものは含まない。"},{"name":"脳性麻痺の座位保持と車椅子シーティング","scope":"脳性麻痺児の座位保持装置の選択、車椅子の設定・シーティングと姿勢保持（骨盤の安定など）を扱う。歩行や動作の指導方法は含まない。"},{"name":"自閉スペクトラム症の特徴と行動","scope":"自閉スペクトラム症の社会的コミュニケーションの障害などの特徴と、クレーン現象をはじめとする特有の行動を扱う。治療・支援の方法は含まない。"},{"name":"運動発達・言語発達のマイルストーン","scope":"寝返りから立ち上がりまでの粗大運動の発達順序・里程標、シャフリングのような発達パターンのバリエーション、発達の順序に沿った促通の考え方、および言語発達（発語と理解）の順序を扱う。特定の発達検査の構成・判定は含まない。"},{"name":"障害児への心理社会的支援と教育環境","scope":"注意欠如・多動症に対する心理社会的治療（行動療法・強化と環境調整など）と、特別支援学校の教育環境・学級編制など、発達障害・障害児を支える支援の場と方法を扱う。疾患の特徴そのものは含まない。"},{"name":"上肢装具と手のスプリント","scope":"末梢神経麻痺（橈骨神経麻痺の下垂手、正中神経麻痺の猿手など）やGuillain-Barré症候群に対する対立装具・コックアップ・ナックルベンダーなどのスプリントの選択と、脳卒中片麻痺の肩関節亜脱臼に対するアームスリングのチェックアウトを扱う。下肢装具は含まない。"},{"name":"下腿義足のアライメントと異常歩行","scope":"下腿義足のベンチ・静的アライメント（初期屈曲角・初期内転角、足部に対するソケットの位置）と、それが崩れたときに生じる足部の浮き上がり・断端の圧迫感・膝折れなどの現象と原因の対応を扱う。大腿義足の異常歩行は含まない。"},{"name":"体幹装具の構造と側弯症の装具療法","scope":"胸腰仙椎装具の骨盤帯・支柱・バンドの位置といった構造と、側弯症の評価（Cobb角、Adams前屈テスト）と装具適応、Boston型・Milwaukee型などの体幹装具の選択を扱う。頸椎装具単独の構造は含まない。"},{"name":"切断の管理と断端の問題","scope":"切断レベルに伴う拘縮・変形（Chopart離断の内反など）、断端の身体計測と周径計測による成熟度評価、拘縮予防のポジショニング、幻肢痛への対応、切断レベルに応じた義足の選択（サイム義足など）を扱う。義足装着後の歩行異常は含まない。"},{"name":"大腿義足の異常歩行と原因","scope":"大腿義足歩行でみられる体幹側屈・過度の腰椎前弯・遊脚相の伸び上がりなどの異常歩行と、義足長・ソケットの初期屈曲角や内転角・股関節周囲筋の筋力低下といった原因との対応を扱う。下腿義足のアライメントは含まない。"},{"name":"松葉杖の調整と歩行","scope":"松葉杖の長さ・脇当てと握りの位置の調整基準、歩行や階段での使い方と免荷の考え方、松葉杖歩行に必要な上肢筋の機能を扱う。車椅子やその他の歩行補助具は含まない。"},{"name":"短下肢装具の足継手の機能と設定","scope":"金属支柱付き短下肢装具の足継手の機能（制動・制限・補助・遊動の区別、クレンザック継手、ダブルクレンザック）と、下肢の異常（尖足・反張膝・膝折れ・痙縮など）に応じた前方制動・後方制動などの設定の組合せを扱う。装具そのものの選択や適合判定は含まない。"},{"name":"短下肢装具の選択と適合","scope":"片麻痺・下垂足などの症例に応じた短下肢装具の種類の選択、外側（T）ストラップなどの付加、適合判定の基準、底屈制動の調整がロッカー機能と歩行に与える効果を扱う。足継手の機能分類そのものは含まない。"},{"name":"義足の構成要素とソケットの適合","scope":"義足を構成する部品の種類と役割を扱う。PTB式・TSB式などのソケット形式と荷重・除圧部位、シリコンライナーの利点、吸着式ソケットや膝継手（可変摩擦膝など）、義足足部（フレックス足など）の機能を含む。アライメント調整そのものは含まない。"},{"name":"装具・支援機器と疾患の組合せ","scope":"装具療法の目的（補助・免荷・矯正など）の総論と、装具名と適応疾患の対応（交互歩行装具と二分脊椎、リーメンビューゲル装具と発育性股関節形成不全、SOMI装具など）、疾患に応じた自助具・支援機器の選択を扱う。個別の装具の構造や適合の詳細は各論点に譲る。"},{"name":"車椅子の寸法と電動車椅子の構造","scope":"車椅子の全幅・全長と方向転換に必要な廊下幅などの寸法計算と、普通型電動車椅子の駆動方式・操縦装置・安全機構を扱う。座位保持やシーティングの詳細は含まない。"},{"name":"長下肢装具・膝装具の構造と適合","scope":"骨盤帯付きを含む両側支柱付き長下肢装具と膝装具について、支柱・半月（大腿・下腿）の位置、股・膝・足継手の軸の基準位置といった適合判定と、筋力低下の症例に対する膝装具の選択を扱う。短下肢装具は含まない。"},{"name":"靴の補正と足部の装具","scope":"靴の補正の種類と効果（ヒール、ウェッジ、ソールウェッジ、メタタルザルバー・パッド、アーチサポート）と、内反足・開張足・槌指・変形性膝関節症・バランス障害などに対する適応の組合せを扱う。短下肢装具本体は含まない。"},{"name":"感度・特異度と尤度比","scope":"疾患の有無と検査結果の2×2表から感度・特異度を求めることと、陽性・陰性尤度比の定義・計算・解釈（検査的中率との区別を含む）を扱う。研究デザインの分類は含めない。"},{"name":"測定尺度と記述統計の基礎","scope":"母集団と標本、名義・順序・間隔・比率尺度の区別、交絡因子などの研究の基本用語と、平均値・中央値・最頻値・分散・標準偏差といった代表値とばらつきの指標、外れ値がこれらに与える影響を扱う。検定法の選択は含めない。"},{"name":"研究デザインとエビデンスレベル","scope":"コホート研究・症例対照研究・横断研究などの観察研究と無作為化比較試験などの介入研究の分類と特徴、無作為化による交絡の抑制、エビデンスレベルの序列と診療ガイドラインの推奨グレードを扱う。検定法の選択や検査指標の計算は含めない。"},{"name":"群間差の検定法の選択","scope":"対応の有無、群の数（2群か3群以上か）、正規分布かどうかによって選ぶ検定法（t検定・対応のあるt検定・一元配置分散分析・Mann-WhitneyのU検定・Wilcoxon符号付順位検定・Kruskal-Wallis検定）を扱う。感度・特異度などの検査指標や記述統計は含めない。"},{"name":"臨床研究の倫理とインフォームドコンセント","scope":"研究参加への同意の取得・撤回と途中中止しても不利益がないこと、事前の説明、匿名化、個人情報と研究データの保管の適切さなど、臨床研究を倫理的に実施する条件を扱う。エビデンスの評価方法そのものは含めない。"}];
